let params = {
  accel: 1.0,
  suppress: 75,
  release: 4.5,
  winter: 0.7,
  lag: 2.5
};

let currentView = 'both';
let animFrame = 0;
let animating = false;

function setView(v) {
  currentView = v;
  ['btnBoth','btnCascade','btnYellow','btnPop'].forEach(id => {
    document.getElementById(id).classList.remove('active');
  });
  const map = { both:'btnBoth', cascade:'btnCascade', yellowstone:'btnYellow', population:'btnPop' };
  document.getElementById(map[v]).classList.add('active');
  draw();
}

function updateParam(key, val) {
  params[key] = parseFloat(val);
  const labels = {
    accel: v => `${parseFloat(v).toFixed(1)}x`,
    suppress: v => `${v}%`,
    release: v => `${parseFloat(v).toFixed(1)}yr`,
    winter: v => `${parseFloat(v).toFixed(2)}`,
    lag: v => `${parseFloat(v).toFixed(1)}yr`
  };
  document.getElementById('v_' + key).textContent = labels[key](val);
  draw();
}

function cascadeValue(t, accel) {
  // Sigmoid-accelerating runaway: slow start, exponential middle, asymptotic top
  // t in years post-ignition, 0-11
  if (t < 0) return 0;
  const x = (t / 11) * accel;
  const base = 1 / (1 + Math.exp(-8 * (x - 0.5)));
  return Math.min(1, base * 1.05);
}

function yellowstoneValue(t, suppress) {
  // Natural accumulation curve minus suppression releases
  // Periodic pressure bleeds keep it artificially low
  const natural = Math.min(1, 0.3 + t * 0.065);
  const suppressed = natural * (1 - suppress / 100 * 0.8);
  // Add micro-variance for realism
  const noise = Math.sin(t * 3.7) * 0.015 + Math.sin(t * 7.1) * 0.008;
  return Math.max(0, suppressed + noise);
}

function populationValue(t, release, winter, accel) {
  // Gradual decline from cascade heat/crop/disease
  // Cliff event at release point from volcanic winter
  if (t < 0) return 1.0;

  // Pre-release slow decline
  const cascadeAtT = cascadeValue(t, accel);
  const gradualDecline = 1 - cascadeAtT * 0.38;

  if (t < release) return Math.max(0, gradualDecline);

  // Post-release volcanic winter cliff
  const postRelease = t - release;
  const winterEffect = winter * 0.72;
  const winterCurve = winterEffect * (1 - Math.exp(-postRelease * 1.2));
  const postPop = gradualDecline - winterCurve;

  // Some recovery after winter but cascade may re-engage
  const cascadePostWinter = cascadeValue(t, accel) - (winter * 0.55);
  const effectiveCascade = Math.max(0, cascadePostWinter);

  return Math.max(0.04, postPop - effectiveCascade * 0.1);
}

function isCascadeArrested(winter, accel) {
  const cascadeAt11 = cascadeValue(11, accel);
  return winter > cascadeAt11 * 0.6;
}

function resize() {
  const rect = canvas.parentElement.getBoundingClientRect();
  canvas.width = rect.width * window.devicePixelRatio;
  canvas.height = rect.height * window.devicePixelRatio;
  canvas.style.width = rect.width + 'px';
  canvas.style.height = rect.height + 'px';
  ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
  draw();
}

function draw() {
  const W = canvas.width / window.devicePixelRatio;
  const H = canvas.height / window.devicePixelRatio;
  ctx.clearRect(0, 0, W, H);

  const pad = { top: 20, right: 30, bottom: 50, left: 55 };
  const cW = W - pad.left - pad.right;
  const cH = H - pad.top - pad.bottom;

  // Background
  ctx.fillStyle = '#050508';
  ctx.fillRect(0, 0, W, H);

  // Grid
  ctx.strokeStyle = 'rgba(255,255,255,0.04)';
  ctx.lineWidth = 1;
  for (let i = 0; i <= 10; i++) {
    const y = pad.top + (i / 10) * cH;
    ctx.beginPath();
    ctx.moveTo(pad.left, y);
    ctx.lineTo(pad.left + cW, y);
    ctx.stroke();
  }
  for (let i = 0; i <= 11; i++) {
    const x = pad.left + (i / 11) * cW;
    ctx.beginPath();
    ctx.moveTo(x, pad.top);
    ctx.lineTo(x, pad.top + cH);
    ctx.stroke();
  }

  const toX = (t) => pad.left + (t / 11) * cW;
  const toY = (v) => pad.top + (1 - v) * cH;

  // Axes
  ctx.strokeStyle = 'rgba(255,255,255,0.15)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(pad.left, pad.top);
  ctx.lineTo(pad.left, pad.top + cH);
  ctx.lineTo(pad.left + cW, pad.top + cH);
  ctx.stroke();

  // X axis labels
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  ctx.font = '9px Share Tech Mono';
  ctx.textAlign = 'center';
  for (let i = 0; i <= 11; i++) {
    const x = toX(i);
    ctx.fillText(i === 0 ? 'T+0' : `+${i}yr`, x, pad.top + cH + 18);
  }

  // Y axis labels
  ctx.textAlign = 'right';
  for (let i = 0; i <= 10; i++) {
    const y = toY(i / 10);
    ctx.fillText(`${i * 10}%`, pad.left - 8, y + 3);
  }

  // Axis titles
  ctx.save();
  ctx.translate(12, pad.top + cH / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(255,255,255,0.2)';
  ctx.font = '9px Share Tech Mono';
  ctx.fillText('INTENSITY / INDEX', 0, 0);
  ctx.restore();

  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(255,255,255,0.2)';
  ctx.font = '9px Share Tech Mono';
  ctx.fillText('YEARS POST CASCADE IGNITION', pad.left + cW / 2, H - 8);

  const STEPS = 220;
  const dt = 11 / STEPS;

  function drawCurve(valueFn, color, glow, lineWidth = 2) {
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.shadowColor = glow;
    ctx.shadowBlur = 8;
    for (let i = 0; i <= STEPS; i++) {
      const t = i * dt;
      const v = valueFn(t);
      const x = toX(t);
      const y = toY(v);
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.shadowBlur = 0;
  }

  function drawArea(valueFn, color, alpha) {
    ctx.beginPath();
    ctx.moveTo(toX(0), toY(0));
    for (let i = 0; i <= STEPS; i++) {
      const t = i * dt;
      const v = valueFn(t);
      ctx.lineTo(toX(t), toY(v));
    }
    ctx.lineTo(toX(11), toY(0));
    ctx.closePath();
    ctx.fillStyle = color.replace(')', `, ${alpha})`).replace('rgb', 'rgba');
    ctx.fill();
  }

  // Detection threshold line
  if (currentView === 'both' || currentView === 'cascade') {
    const detX = toX(params.lag);
    ctx.setLineDash([6, 4]);
    ctx.strokeStyle = 'rgba(204,68,255,0.5)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(detX, pad.top);
    ctx.lineTo(detX, pad.top + cH);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = 'rgba(204,68,255,0.7)';
    ctx.font = '9px Share Tech Mono';
    ctx.textAlign = 'left';
    ctx.fillText('DETECTION', detX + 4, pad.top + 14);
  }

  // Cascade ignition marker
  ctx.setLineDash([4, 4]);
  ctx.strokeStyle = 'rgba(255,58,26,0.3)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(toX(0), pad.top);
  ctx.lineTo(toX(0), pad.top + cH);
  ctx.stroke();
  ctx.setLineDash([]);

  // Release event marker
  if (currentView === 'both' || currentView === 'yellowstone' || currentView === 'population') {
    const relX = toX(params.release);
    ctx.strokeStyle = 'rgba(245,166,35,0.4)';
    ctx.lineWidth = 1;
    ctx.setLineDash([3,3]);
    ctx.beginPath();
    ctx.moveTo(relX, pad.top);
    ctx.lineTo(relX, pad.top + cH);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = 'rgba(245,166,35,0.7)';
    ctx.font = '9px Share Tech Mono';
    ctx.textAlign = 'right';
    ctx.fillText('RELEASE', relX - 4, pad.top + 14);
  }

  // Draw curves based on view
  const showCascade = currentView === 'both' || currentView === 'cascade';
  const showYellow = currentView === 'both' || currentView === 'yellowstone';
  const showPop = currentView === 'both' || currentView === 'population';

  if (showYellow) {
    drawArea(t => yellowstoneValue(t, params.suppress), 'rgb(245,166,35)', 0.06);
    drawCurve(t => yellowstoneValue(t, params.suppress), 'rgb(245,166,35)', 'rgb(245,166,35)', 2);
  }

  if (showPop) {
    drawArea(t => populationValue(t, params.release, params.winter, params.accel), 'rgb(74,158,255)', 0.05);
    drawCurve(t => populationValue(t, params.release, params.winter, params.accel), 'rgb(74,158,255)', 'rgb(74,158,255)', 2.5);
  }

  if (showCascade) {
    drawArea(t => cascadeValue(t, params.accel), 'rgb(255,58,26)', 0.07);
    drawCurve(t => cascadeValue(t, params.accel), 'rgb(255,58,26)', 'rgb(255,58,26)', 2.5);
  }

  // Intersection zone highlight
  if (currentView === 'both') {
    let intersectT = null;
    for (let i = 1; i <= STEPS; i++) {
      const t = i * dt;
      const prevT = (i-1) * dt;
      const cv = cascadeValue(t, params.accel);
      const pv = populationValue(t, params.release, params.winter, params.accel);
      const cvPrev = cascadeValue(prevT, params.accel);
      const pvPrev = populationValue(prevT, params.release, params.winter, params.accel);
      if (cvPrev > pvPrev && cv <= pv || cvPrev < pvPrev && cv >= pv) {
        intersectT = t;
        break;
      }
    }
    if (intersectT !== null) {
      const ix = toX(intersectT);
      const iy = toY(cascadeValue(intersectT, params.accel));
      ctx.beginPath();
      ctx.arc(ix, iy, 6, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(255,255,255,0.6)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      ctx.fillStyle = 'rgba(255,255,255,0.1)';
      ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.5)';
      ctx.font = '9px Share Tech Mono';
      ctx.textAlign = 'left';
      ctx.fillText('DECISION NODE', ix + 10, iy - 4);
    }
  }

  updateMetrics();
}

function updateMetrics() {
  const popAtRelease = populationValue(params.release, params.release, params.winter, params.accel);
  const popFinal = populationValue(11, params.release, params.winter, params.accel);
  const arrested = isCascadeArrested(params.winter, params.accel);

  document.getElementById('m_ignition').textContent = 'T+0';
  document.getElementById('m_detect').textContent = `+${params.lag.toFixed(1)}yr`;
  document.getElementById('m_poprelease').textContent = `${(popAtRelease * 100).toFixed(0)}%`;
  document.getElementById('m_popfinal').textContent = `${(popFinal * 100).toFixed(0)}%`;
  document.getElementById('m_arrested').textContent = arrested ? 'YES' : 'NO';
  document.getElementById('m_gap').textContent = `${params.release.toFixed(1)}yr`;

  const popReleaseVal = (popAtRelease * 100).toFixed(0);
  const popFinalVal = (popFinal * 100).toFixed(0);
  const gapYr = params.release.toFixed(1);
  const detYr = params.lag.toFixed(1);

  const verdictEl = document.getElementById('verdictText');
  if (!arrested) {
    verdictEl.innerHTML = `At these parameters, the volcanic winter is <span style="color:var(--cascade)">insufficient to arrest the cascade</span>. Release timing of +${gapYr}yr with winter severity ${params.winter.toFixed(2)} produces ${popFinalVal}% surviving population — but the Venus runaway continues. Both outcomes converge on terminal.`;
  } else if (popFinalVal < 8) {
    verdictEl.innerHTML = `Cascade is arrested. Population surviving: <span style="color:var(--cascade)">${popFinalVal}%</span>. The long-thinker calculus holds — biosphere preserved at civilizational cost. Detection lag of ${detYr}yr means public awareness arrives <span style="color:var(--cascade)">after the decision is already executed</span>.`;
  } else {
    verdictEl.innerHTML = `Cascade arrested. <span style="color:var(--population)">${popFinalVal}%</span> population survives. Release at +${gapYr}yr — ${(params.release - params.lag).toFixed(1)}yr before human detection threshold. The window between decision and public knowledge: <span style="color:var(--yellowstone)">${Math.max(0, params.release - params.lag).toFixed(1)} years of silence</span>.`;
  }

  // Event log
  const log = document.getElementById('eventLog');
  const events = [
    { cls: 'critical', text: `T+0 — CASCADE IGNITION. Feedback threshold crossed. No public signal.` },
    { cls: 'info', text: `T+${params.lag.toFixed(1)}yr — First detectable human mortality signal. Framed as climate/disease.` },
    { cls: 'warning', text: `T+${(params.release - 0.5).toFixed(1)}yr — Suppression infrastructure ordered to stand down.` },
    { cls: 'warning', text: `T+${params.release.toFixed(1)}yr — YELLOWSTONE RELEASE. Juxtapositional interference withdrawn.` },
    { cls: 'critical', text: `T+${(params.release + 0.8).toFixed(1)}yr — Volcanic winter onset. Global temperature drop -8°C to -14°C.` },
    { cls: 'info', text: `T+${(params.release + 1.5).toFixed(1)}yr — Agriculture collapse 90%+ northern hemisphere.` },
    { cls: 'critical', text: `T+${(params.release + 2.5).toFixed(1)}yr — Population at ${(popAtRelease * 100 * (1 - params.winter * 0.4)).toFixed(0)}%. Organized resistance non-functional.` },
    { cls: 'info', text: `T+11yr — Surviving population: ${popFinalVal}%. Cascade status: ${arrested ? 'ARRESTED' : 'CONTINUING'}.` },
  ];
  log.innerHTML = events.map(e => `<div class="entry ${e.cls}">${e.text}</div>`).join('');
}

window.addEventListener('resize', resize);
resize();
</script>
</body>
</html>

