// ============================================================
// CALIBRATED PARAMETERS — grounded in real data
// Yellowstone winter: 100yr geological floor (UCSB/Kennett 2017)
//   adjusted to 111yr for hot-planet state (elevated albedo feedback
//   on a warming baseline produces stronger ice-ocean positive loop)
// Cascade: tipping cascade ignition model — NOT full Venus runaway
//   but self-sustaining irreversible on human timescales
//   11yr to locked state per Jade Bennett framework
// Population floor: derived from 111yr agricultural collapse
//   Pinatubo (1000x smaller) = 3yr cooling, -0.7C, measurable famine
//   Yellowstone scale = stratospheric sulfate persisting ~8-12yr
//   then ice-albedo feedback extends to 111yr total
//   Northern hemisphere agriculture collapse ~95% within 3yr of release
//   Survivable population: ~4-8% globally (remote/equatorial/prepared)
// ============================================================

const WINTER_DURATION = 111;   // years — calibrated hot-planet figure
const CASCADE_WINDOW = 11;     // years to locked tipping state
const TIMELINE = 130;          // total simulation span (years)
const TEMP_DROP_PEAK = 11.5;   // °C peak drop — Yellowstone scale, hot planet amplified
const TEMP_DROP_FLOOR = 3.0;   // °C residual after aerosol dissipation (ice-albedo sustained)
const POP_FLOOR = 0.05;        // 5% absolute survival floor — 111yr winter, no agriculture

let params = {
  accel: 1.0,       // cascade acceleration multiplier
  suppress: 78,     // suppression efficiency % (calibrated — Yellowstone overdue by ~10kyr)
  release: 5.0,     // years post-ignition when suppression withdrawn
  winterSeverity: 0.88,  // 1.0 = full 111yr calibrated winter
  lag: 3.0          // years between cascade ignition and first public mortality signal
};

let currentView = 'both';

function setView(v) {
  currentView = v;
  ['btnBoth','btnCascade','btnYellow','btnPop'].forEach(id => {
    document.getElementById(id).classList.remove('active');
  });
  const map = { both:'btnBoth', cascade:'btnCascade', yellowstone:'btnYellow', population:'btnPop' };
  document.getElementById(map[v]).classList.add('active');
  draw();
}

function updateParam(key, val) {
  params[key] = parseFloat(val);
  const labels = {
    accel: v => `${parseFloat(v).toFixed(1)}x`,
    suppress: v => `${v}%`,
    release: v => `+${parseFloat(v).toFixed(1)}yr`,
    winterSeverity: v => `${(parseFloat(v)*100).toFixed(0)}%`,
    lag: v => `${parseFloat(v).toFixed(1)}yr`
  };
  document.getElementById('v_' + key).textContent = labels[key](val);
  draw();
}

// Tipping cascade index: 0 = pre-ignition baseline, 1.0 = locked irreversible state
// Sigmoid shape: slow start (feedback accumulation), exponential middle, asymptote
// At t=11yr the cascade is locked regardless of intervention
function cascadeIndex(t, accel) {
  if (t < 0) return 0;
  const normalised = (t / CASCADE_WINDOW) * accel;
  const sigmoid = 1 / (1 + Math.exp(-9 * (normalised - 0.48)));
  return Math.min(1.0, sigmoid * 1.04);
}

// Yellowstone caldera pressure index: naturally suppressed by juxtapositional bleeds
// After release point: rapid decompression event, then post-eruption aerosol curve
function yellowstoneIndex(t, releaseT, suppress) {
  if (t < releaseT) {
    // Suppressed accumulation with periodic micro-releases (noise)
    const natural = Math.min(0.95, 0.28 + t * 0.058);
    const suppressed = natural * (1 - (suppress / 100) * 0.82);
    const noise = Math.sin(t * 4.1) * 0.012 + Math.sin(t * 9.3) * 0.006;
    return Math.max(0.02, suppressed + noise);
  }
  // Post-release: eruption spike then aerosol decay curve
  const postR = t - releaseT;
  // Eruption spike peaks at ~0.5yr then sulfate aerosol decay
  const spike = Math.exp(-postR * 0.6) * 0.95;
  // Ice-albedo feedback sustains secondary elevated state for decades
  const iceAlbedo = 0.35 * Math.exp(-postR / 40) * (postR > 2 ? 1 : postR / 2);
  return Math.max(0, spike + iceAlbedo);
}

// Global mean temperature anomaly (°C, negative = cooling)
// Used internally to drive population model
function tempAnomaly(t, releaseT, winterSeverity) {
  if (t < releaseT) {
    // Pre-release: cascade warming trend (+0.15°C/yr accelerating)
    return cascadeIndex(t, params.accel) * 2.8;
  }
  const postR = t - releaseT;
  const peakDrop = TEMP_DROP_PEAK * winterSeverity;
  const floorDrop = TEMP_DROP_FLOOR * winterSeverity;
  // Phase 1: aerosol cooling — rapid onset, peak ~2yr, decay ~8-12yr
  const aerosolPhase = peakDrop * Math.exp(-postR / 6) * Math.min(1, postR / 1.5);
  // Phase 2: ice-albedo sustained cooling — slower decay over ~100yr
  const icePhase = floorDrop * (1 - Math.exp(-postR / 8)) * Math.exp(-postR / 85);
  const totalDrop = -(aerosolPhase + icePhase);
  // Cascade contribution still present if not arrested
  const cascadeWarmth = cascadeIndex(t, params.accel) * 2.8 * (1 - winterSeverity * 0.9);
  return totalDrop + cascadeWarmth;
}

// Population survival index 0-1
// Cascade pre-release: heat stress, famine, disease, infrastructure collapse
// Post-release: volcanic winter agricultural collapse is the primary driver
// 111yr winter = no recovery of global agriculture within simulation window
function populationIndex(t, releaseT, winterSeverity, accel) {
  if (t < 0) return 1.0;

  const cascAt = cascadeIndex(t, accel);

  if (t < releaseT) {
    // Gradual cascade-driven mortality: heat, famine, conflict, disease
    // ~35% mortality by the time cascade is locked (t=11yr equivalent)
    return Math.max(0, 1 - cascAt * 0.36);
  }

  // Pre-release population at moment of Yellowstone event
  const popAtRelease = Math.max(0, 1 - cascadeIndex(releaseT, accel) * 0.36);
  const postR = t - releaseT;

  // Agricultural collapse curve:
  // Year 1-3: 60% of remaining food supply gone (aerosol phase kills crops globally)
  // Year 3-15: sustained collapse, starvation, conflict over remaining resources
  // Year 15-111: ice-albedo sustained cooling — no recovery, slow attrition
  // Year 111+: very slow recovery begins
  const agriCollapse = winterSeverity * 0.88 * (1 - Math.exp(-postR / 2.5));

  // Cascade continues to contribute warmth if not arrested — creates "cold-hot" oscillation
  // that's actually worse for agriculture than sustained cold
  const residualCascade = cascadeIndex(t, accel) * (1 - winterSeverity * 0.92) * 0.15;

  const survivalFraction = popAtRelease * (1 - agriCollapse) - residualCascade;
  return Math.max(POP_FLOOR * winterSeverity, survivalFraction);
}

function isCascadeArrested(winterSeverity) {
  // Winter arrests cascade if it suppresses temp enough to break the feedback loop
  // Requires sustained -3°C or more through the critical 11yr window
  return winterSeverity >= 0.65;
}

function winterEndYear(releaseT, winterSeverity) {
  // Calibrated: 111yr at full severity, scaled by severity parameter
  return releaseT + Math.round(WINTER_DURATION * winterSeverity);
}

