@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700;900&family=Inconsolata:wght@300;400;600&display=swap');

:root {
  --bg: #03040a;
  --panel: #070810;
  --border: #12142a;
  --border-bright: #1e2245;
  --cascade: #ff2200;
  --winter: #00aaff;
  --pop-surface: #ff6600;
  --pop-prepared: #00ff88;
  --braided: #00ffcc;
  --nonbraided: #ff4466;
  --gold: #d4a843;
  --text: #b8bcd4;
  --dim: #444466;
  --bright: #e8ecff;
  --glow-red: 0 0 24px rgba(255,34,0,0.5);
  --glow-blue: 0 0 24px rgba(0,170,255,0.5);
  --glow-green: 0 0 24px rgba(0,255,136,0.5);
  --glow-teal: 0 0 24px rgba(0,255,204,0.5);
  --glow-pink: 0 0 24px rgba(255,68,102,0.5);
  --glow-gold: 0 0 24px rgba(212,168,67,0.4);
}

* { margin:0; padding:0; box-sizing:border-box; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inconsolata', monospace;
  min-height: 100vh;
  overflow-x: hidden;
}

/* Atmospheric background */
body::before {
  content:'';
  position:fixed;
  inset:0;
  background:
    radial-gradient(ellipse 60% 40% at 20% 20%, rgba(255,34,0,0.03) 0%, transparent 70%),
    radial-gradient(ellipse 50% 30% at 80% 80%, rgba(0,170,255,0.03) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 50% 50%, rgba(0,255,204,0.02) 0%, transparent 70%);
  pointer-events:none;
  z-index:0;
}

.scanlines {
  position:fixed;
  inset:0;
  background: repeating-linear-gradient(0deg, transparent, transparent 3px, rgba(0,0,0,0.06) 3px, rgba(0,0,0,0.06) 4px);
  pointer-events:none;
  z-index:1000;
}

.wrapper { position:relative; z-index:1; }

/* ── HEADER ── */
header {
  padding: 32px 48px 24px;
  border-bottom: 1px solid var(--border-bright);
  position:relative;
  overflow:hidden;
}
header::after {
  content:'';
  position:absolute;
  bottom:0; left:0; right:0; height:1px;
  background: linear-gradient(90deg, transparent 0%, var(--cascade) 30%, var(--braided) 70%, transparent 100%);
  opacity:0.5;
}

.header-grid {
  display:grid;
  grid-template-columns: 1fr auto;
  align-items:start;
  gap:24px;
}

.title-block h1 {
  font-family: 'Orbitron', monospace;
  font-weight:900;
  font-size: 36px;
  letter-spacing: 4px;
  color: var(--bright);
  line-height:1;
  margin-bottom:6px;
}
.title-block h1 em {
  color: var(--cascade);
  font-style:normal;
  text-shadow: var(--glow-red);
}
.title-block h1 span {
  color: var(--braided);
  text-shadow: var(--glow-teal);
}

.subtitle {
  font-size:10px;
  letter-spacing:3px;
  color: var(--dim);
  text-transform:uppercase;
  margin-top:4px;
}

.header-meta {
  text-align:right;
  font-size:10px;
  color: var(--dim);
  line-height:2;
}
.header-meta .live {
  color: var(--cascade);
  animation: pulse 1.6s infinite;
}
.header-meta .author {
  color: var(--gold);
  font-size:9px;
  letter-spacing:2px;
}

@keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.2} }

/* ── TAB NAV ── */
.tab-nav {
  display:flex;
  border-bottom: 1px solid var(--border-bright);
  padding: 0 48px;
  background: rgba(0,0,0,0.3);
}
.tab {
  padding: 14px 32px;
  font-family:'Orbitron', monospace;
  font-size:10px;
  font-weight:700;
  letter-spacing:3px;
  color: var(--dim);
  cursor:pointer;
  border-bottom: 2px solid transparent;
  transition: all 0.2s;
  text-transform:uppercase;
  position:relative;
}
.tab:hover { color: var(--text); }
.tab.active {
  color: var(--bright);
  border-bottom-color: var(--gold);
}
.tab.active::after {
  content:'';
  position:absolute;
  bottom:-2px; left:0; right:0; height:2px;
  background: var(--gold);
  box-shadow: var(--glow-gold);
}

/* ── SIMULATION PANELS ── */
.sim-panel {
  display:none;
  padding: 32px 48px;
}
.sim-panel.active { display:block; }

/* ── TWO-COLUMN LAYOUT ── */
.sim-layout {
  display:grid;
  grid-template-columns: 1fr 300px;
  gap: 24px;
  height: calc(100vh - 200px);
  min-height: 520px;
}

.chart-col {
  display:flex;
  flex-direction:column;
  gap:16px;
}

.chart-wrap {
  flex:1;
  position:relative;
  min-height:300px;
}

canvas {
  display:block;
  width:100%;
  height:100%;
}

.chart-label {
  font-family:'Orbitron', monospace;
  font-size:10px;
  letter-spacing:3px;
  color: var(--dim);
  text-transform:uppercase;
  margin-bottom:8px;
}

.view-btns {
  display:flex;
  gap:6px;
  flex-wrap:wrap;
}

/* ── SIDEBAR ── */
.sidebar-col {
  display:flex;
  flex-direction:column;
  gap:16px;
  overflow-y:auto;
  padding-right:4px;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  padding:16px;
  position:relative;
}
.panel::before {
  content:'';
  position:absolute;
  top:0; left:0; right:0; height:1px;
  background: linear-gradient(90deg, transparent, var(--border-bright), transparent);
}

.panel-title {
  font-family:'Orbitron', monospace;
  font-size:9px;
  letter-spacing:3px;
  color: var(--dim);
  text-transform:uppercase;
  margin-bottom:12px;
  padding-bottom:8px;
  border-bottom:1px solid var(--border);
}

/* Controls */
.ctrl { margin-bottom:12px; }
.ctrl-label {
  font-size:9px;
  color: var(--dim);
  letter-spacing:1px;
  display:flex;
  justify-content:space-between;
  margin-bottom:5px;
}
.ctrl-label span { color: var(--text); font-size:10px; }

input[type=range] {
  -webkit-appearance:none;
  width:100%;
  height:1px;
  background: var(--border-bright);
  outline:none;
}
input[type=range]::-webkit-slider-thumb {
  -webkit-appearance:none;
  width:10px; height:10px;
  background: var(--gold);
  cursor:pointer;
  border-radius:0;
  box-shadow: 0 0 8px rgba(212,168,67,0.5);
}

/* Metrics */
.metrics { display:grid; grid-template-columns:1fr 1fr; gap:6px; }
.metric {
  background: rgba(255,255,255,0.02);
  border:1px solid var(--border);
  padding:8px 10px;
}
.metric-label {
  font-size:8px;
  color: var(--dim);
  letter-spacing:1px;
  text-transform:uppercase;
  margin-bottom:3px;
}
.metric-value {
  font-family:'Orbitron', monospace;
  font-size:14px;
  font-weight:700;
}
.mv-red   { color:var(--cascade);    text-shadow:var(--glow-red); }
.mv-blue  { color:var(--winter);     text-shadow:var(--glow-blue); }
.mv-green { color:var(--pop-prepared); text-shadow:var(--glow-green); }
.mv-teal  { color:var(--braided);    text-shadow:var(--glow-teal); }
.mv-pink  { color:var(--nonbraided); text-shadow:var(--glow-pink); }
.mv-gold  { color:var(--gold);       text-shadow:var(--glow-gold); }
.mv-orange { color:var(--pop-surface); }

/* Legend */
.legend-item {
  display:flex; align-items:center; gap:8px;
  font-size:10px; margin-bottom:7px;
}
.leg-line {
  width:20px; height:2px; flex-shrink:0;
}
.leg-dash {
  width:20px; height:0; flex-shrink:0;
  border-top:2px dashed currentColor;
}

/* Event log */
.event-log {
  font-size:9px;
  line-height:1.9;
  max-height:140px;

