body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inconsolata', monospace;
  min-height: 100vh;
  overflow-x: hidden;
  -webkit-text-size-adjust: 100%;
}

body::before {
  content:'';
  position:fixed;
  inset:0;
  background:
    radial-gradient(ellipse 60% 40% at 20% 20%, rgba(255,34,0,0.03) 0%, transparent 70%),
    radial-gradient(ellipse 50% 30% at 80% 80%, rgba(0,170,255,0.03) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 50% 50%, rgba(0,255,204,0.02) 0%, transparent 70%);
  pointer-events:none;
  z-index:0;
}

.scanlines {
  position:fixed;
  inset:0;
  background: repeating-linear-gradient(0deg, transparent, transparent 3px, rgba(0,0,0,0.06) 3px, rgba(0,0,0,0.06) 4px);
  pointer-events:none;
  z-index:1000;
}

.wrapper { position:relative; z-index:1; }

/* ── HEADER ── */
header {
  padding: 20px 16px 16px;
  border-bottom: 1px solid var(--border-bright);
  position:relative;
  overflow:hidden;
}
header::after {
  content:'';
  position:absolute;
  bottom:0; left:0; right:0; height:1px;
  background: linear-gradient(90deg, transparent 0%, var(--cascade) 30%, var(--braided) 70%, transparent 100%);
  opacity:0.5;
}

.header-grid {
  display:flex;
  flex-direction:column;
  gap:10px;
}

.title-block h1 {
  font-family: 'Orbitron', monospace;
  font-weight:900;
  font-size: clamp(18px, 5vw, 36px);
  letter-spacing: clamp(1px, 0.5vw, 4px);
  color: var(--bright);
  line-height:1.1;
  margin-bottom:5px;
}
.title-block h1 em {
  color: var(--cascade);
  font-style:normal;
  text-shadow: var(--glow-red);
}
.title-block h1 span {
  color: var(--braided);
  text-shadow: var(--glow-teal);
}

.subtitle {
  font-size: clamp(8px, 2vw, 10px);
  letter-spacing: 1.5px;
  color: var(--dim);
  text-transform:uppercase;
  margin-top:3px;
  line-height:1.5;
}

.header-meta {
  display:flex;
  flex-wrap:wrap;
  gap:8px 16px;
  font-size: clamp(9px, 2vw, 10px);
  color: var(--dim);
  line-height:1.6;
}
.header-meta .live { color: var(--cascade); animation: pulse 1.6s infinite; }
.header-meta .author { color: var(--gold); font-size:9px; letter-spacing:1.5px; }

@keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.2} }

/* ── TAB NAV ── */
.tab-nav {
  display:flex;
  border-bottom: 1px solid var(--border-bright);
  padding: 0 0;
  background: rgba(0,0,0,0.3);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.tab-nav::-webkit-scrollbar { display:none; }

.tab {
  flex-shrink:0;
  padding: 14px 16px;
  font-family:'Orbitron', monospace;
  font-size: clamp(8px, 2vw, 10px);
  font-weight:700;
  letter-spacing: 1.5px;
  color: var(--dim);
  cursor:pointer;
  border-bottom: 2px solid transparent;
  transition: all 0.2s;
  text-transform:uppercase;
  position:relative;
  white-space:nowrap;
  -webkit-tap-highlight-color: transparent;
}
.tab:hover { color: var(--text); }
.tab.active { color: var(--bright); border-bottom-color: var(--gold); }
.tab.active::after {
  content:'';
  position:absolute;
  bottom:-2px; left:0; right:0; height:2px;
  background: var(--gold);
  box-shadow: var(--glow-gold);
}

/* ── SIMULATION PANELS ── */
.sim-panel { display:none; padding: 12px 12px 32px; }
.sim-panel.active { display:block; }

/* ── LAYOUT: mobile = single column, desktop = two column ── */
.sim-layout {
  display:flex;
  flex-direction:column;
  gap: 16px;
}

@media (min-width: 900px) {
  header { padding: 28px 40px 20px; }
  .header-grid { flex-direction:row; align-items:start; justify-content:space-between; }
  .header-meta { flex-direction:column; text-align:right; gap:0; }
  .tab-nav { padding: 0 40px; }
  .sim-panel { padding: 24px 40px 40px; }
  .sim-layout {
    display:grid;
    grid-template-columns: 1fr 300px;
    gap: 24px;
    height: calc(100vh - 200px);
    min-height: 520px;
  }
  .sidebar-col { overflow-y:auto; }
}

/* ── CHART ── */
.chart-col {
  display:flex;
  flex-direction:column;
  gap:12px;
}

.chart-wrap {
  position:relative;
  width:100%;
  height: 52vw;
  min-height: 240px;
  max-height: 420px;
}

@media (min-width: 900px) {
  .chart-wrap {
    flex:1;
    height:auto;
    max-height:none;
  }
}

canvas { display:block; width:100%; height:100%; }

.chart-label {
  font-family:'Orbitron', monospace;
  font-size: clamp(8px, 2vw, 10px);
  letter-spacing: 1.5px;
  color: var(--dim);
  text-transform:uppercase;
  line-height:1.4;
}

.view-btns {
  display:flex;
  gap:5px;
  flex-wrap:wrap;
}

/* ── SIDEBAR / PANELS BELOW CHART ON MOBILE ── */
.sidebar-col {
  display:flex;
  flex-direction:column;
  gap:12px;
}

/* Collapsible panels on mobile */
.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  padding: 12px;
  position:relative;
}
.panel::before {
  content:'';
  position:absolute;
  top:0; left:0; right:0; height:1px;
  background: linear-gradient(90deg, transparent, var(--border-bright), transparent);
}

.panel-title {
  font-family:'Orbitron', monospace;
  font-size: clamp(8px, 2vw, 9px);
  letter-spacing: 2px;
  color: var(--dim);
  text-transform:uppercase;
  margin-bottom:10px;
  padding-bottom:8px;
  border-bottom:1px solid var(--border);
  display:flex;
  justify-content:space-between;
  align-items:center;
  cursor:pointer;
  -webkit-tap-highlight-color: transparent;
  user-select:none;
}
.panel-title::after {
  content:'▾';
  font-size:11px;
  color: var(--dim);
  transition: transform 0.2s;
}
.panel.collapsed .panel-title::after { transform: rotate(-90deg); }
.panel-body { overflow:hidden; transition: max-height 0.25s ease; }
.panel.collapsed .panel-body { max-height:0 !important; }

/* Controls */
.ctrl { margin-bottom:14px; }
.ctrl-label {
  font-size: clamp(9px, 2vw, 9px);
  color: var(--dim);
  letter-spacing:1px;
  display:flex;
  justify-content:space-between;
  margin-bottom:8px;
}
.ctrl-label span { color: var(--text); font-size:11px; }

input[type=range] {
  -webkit-appearance:none;
  width:100%;
  height:4px;
  background: var(--border-bright);
  outline:none;
  border-radius:2px;
  cursor:pointer;
}
input[type=range]::-webkit-slider-thumb {
  -webkit-appearance:none;
  width:20px; height:20px;
  background: var(--gold);
  cursor:pointer;
  border-radius:2px;
  box-shadow: 0 0 8px rgba(212,168,67,0.5);
}
input[type=range]::-moz-range-thumb {
  width:20px; height:20px;
  background: var(--gold);
  border:none;
  border-radius:2px;
}

/* Metrics */
.metrics { display:grid; grid-template-columns:1fr 1fr; gap:6px; }
.metric {
  background: rgba(255,255,255,0.02);
  border:1px solid var(--border);
  padding:8px 10px;
}
.metric-label {
  font-size: clamp(8px, 1.8vw, 8px);
  color: var(--dim);
  letter-spacing:0.5px;
  text-transform:uppercase;
  margin-bottom:3px;
  line-height:1.3;
}
.metric-value {
  font-family:'Orbitron', monospace;
  font-size: clamp(13px, 3.5vw, 15px);
  font-weight:700;
}
