// ════════════════════════════════════════
// COLLAPSIBLE PANELS
// ════════════════════════════════════════
function togglePanel(titleEl) {
  const panel = titleEl.parentElement;
  const body  = panel.querySelector('.panel-body');
  if(!body) return;
  const isCollapsed = panel.classList.contains('collapsed');
  if(isCollapsed) {
    panel.classList.remove('collapsed');
    body.style.maxHeight = body.scrollHeight + 'px';
    // Let it auto after expand
    setTimeout(()=>{ body.style.maxHeight = 'none'; }, 300);
  } else {
    body.style.maxHeight = body.scrollHeight + 'px';
    requestAnimationFrame(()=>{
      body.style.maxHeight = '0';
      panel.classList.add('collapsed');
    });
  }
}

// Set all panel-body heights to 'none' on load so they're open
document.querySelectorAll('.panel-body').forEach(b => {
  b.style.maxHeight = 'none';
});

