function resizeCanvas(canvas) {
  const wrap = canvas.parentElement; // .chart-wrap
  const dpr = window.devicePixelRatio||1;
  const w = wrap.offsetWidth;
  const h = wrap.offsetHeight;
  canvas.width  = w * dpr;
  canvas.height = h * dpr;
  canvas.style.width  = w + 'px';
  canvas.style.height = h + 'px';
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  return { w, h, ctx };
}

function drawGrid(ctx, W, H, pad, xSteps, ySteps) {
  ctx.strokeStyle = 'rgba(255,255,255,0.03)';
  ctx.lineWidth = 1;
  for(let i=0;i<=ySteps;i++){
    const y = pad.t + (i/ySteps)*( H-pad.t-pad.b);
    ctx.beginPath(); ctx.moveTo(pad.l,y); ctx.lineTo(W-pad.r,y); ctx.stroke();
  }
  for(let i=0;i<=xSteps;i++){
    const x = pad.l + (i/xSteps)*(W-pad.l-pad.r);
    ctx.beginPath(); ctx.moveTo(x,pad.t); ctx.lineTo(x,H-pad.b); ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(255,255,255,0.12)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(pad.l,pad.t); ctx.lineTo(pad.l,H-pad.b); ctx.lineTo(W-pad.r,H-pad.b);
  ctx.stroke();
}

function drawCurve(ctx, pts, color, glow, lw=2, dash=[]) {
  ctx.save();
  ctx.beginPath();
  ctx.strokeStyle = color;
  ctx.lineWidth = lw;
  ctx.shadowColor = glow||color;
  ctx.shadowBlur = glow ? 10 : 0;
  if(dash.length) ctx.setLineDash(dash);
  pts.forEach((p,i) => i===0 ? ctx.moveTo(p[0],p[1]) : ctx.lineTo(p[0],p[1]));
  ctx.stroke();
  ctx.restore();
}

function drawArea(ctx, pts, color, alpha, W, H, pad) {
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(pts[0][0], H-pad.b);
  pts.forEach(p => ctx.lineTo(p[0],p[1]));
  ctx.lineTo(pts[pts.length-1][0], H-pad.b);
  ctx.closePath();
  const col = color.replace('rgb(','rgba(').replace(')',`,${alpha})`);
  ctx.fillStyle = col.includes('rgba') ? col : color;
  ctx.globalAlpha = alpha;
  ctx.fill();
  ctx.restore();
}

function vline(ctx, x, color, dash=[]) {
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = 1;
  ctx.globalAlpha = 0.5;
  if(dash.length) ctx.setLineDash(dash);
  ctx.beginPath();
  ctx.moveTo(x, ctx._padT||0);
  ctx.lineTo(x, ctx._padB||600);
  ctx.stroke();
  ctx.restore();
}

// ════════════════════════════════════════
// SIM I — CASCADE / WINTER / SURVIVAL
// ════════════════════════════════════════
const S1 = {
  accel: 1.0, supp: 78, rel: 5.0, wint: 0.88, lag: 3.0, prep: 0.1,
  view: 'all'
};

const WINTER_MAX = 111; // yr calibrated
const CASCADE_LOCK = 11; // yr to locked state
const TIMELINE_1 = 130; // yr display

function s1_cascade(t) {
  if(t<0) return 0;
  return clamp(sigmoid(t/CASCADE_LOCK*S1.accel, 9, 0.48)*1.04, 0, 1);
}

function s1_yellowstone(t) {
  const rel = S1.rel;
  if(t < rel) {
    const nat = clamp(0.28 + t*0.058, 0, 0.95);
    const sup = nat*(1-(S1.supp/100)*0.82);
    const noise = Math.sin(t*4.1)*0.012 + Math.sin(t*9.3)*0.006;
    return clamp(sup+noise, 0.02, 1);
  }
  const p = t-rel;
  const spike = Math.exp(-p*0.55)*0.95;
  const ice   = 0.32*Math.exp(-p/40)*(p>2?1:p/2);
  return clamp(spike+ice, 0, 1);
}

function s1_tempAnomaly(t) {
  // Returns °C anomaly — positive = warming, negative = cooling
  const rel = S1.rel;
  const w = S1.wint;
  if(t < rel) return s1_cascade(t)*2.8;
  const p = t-rel;
  const peak = 11.5*w;
  const floor = 3.0*w;
  const aerosol = peak*Math.exp(-p/6)*Math.min(1,p/1.5);
  const ice     = floor*(1-Math.exp(-p/8))*Math.exp(-p/85);
  const cascContrib = s1_cascade(t)*2.8*(1-w*0.92);
  return -aerosol - ice + cascContrib;
}

function s1_surfacePop(t) {
  const rel = S1.rel;
  const w = S1.wint;
  if(t<0) return 1;
  const casc = s1_cascade(t);
  if(t < rel) return clamp(1-casc*0.36, 0, 1);
  const popAtRel = clamp(1-s1_cascade(rel)*0.36, 0, 1);
  const p = t-rel;
  // Aerosol phase wipes agriculture ~3yr, ice phase sustains
  const agriCollapse = w*0.9*(1-Math.exp(-p/2.8));
  const residual = s1_cascade(t)*(1-w*0.94)*0.1;
  return clamp(popAtRel*(1-agriCollapse)-residual, 0.01, 1);
}

function s1_preparedPop(t) {
  // Prepared population: sealed agriculture, geothermal, no surface exposure
  // Winter is irrelevant to food supply; attrition from medical/accident/psychology
  const rel = S1.rel;
  if(t < rel) return 1.0; // fully intact pre-release
  const p = t-rel;
  // Very slow internal attrition — bunker life is survivable but not zero-loss
  const attrition = 0.08*(1-Math.exp(-p/30)); // ~8% loss over 111yr max
  return clamp(1-attrition, 0.88, 1);
}

function s1param(k,v) {
  S1[k] = parseFloat(v);
  const fmt = {
    accel: v=>`${parseFloat(v).toFixed(1)}×`,
    supp:  v=>`${v}%`,
    rel:   v=>`+${parseFloat(v).toFixed(1)}yr`,
    wint:  v=>`${(parseFloat(v)*100).toFixed(0)}%`,
    lag:   v=>`${parseFloat(v).toFixed(1)}yr`,
    prep:  v=>`${parseFloat(v).toFixed(2)}%`
  };
  document.getElementById('v1_'+k).textContent = fmt[k](v);
  drawSim1();
}

function s1view(v) {
  S1.view = v;
  ['all','cascade','winter','pop','temp'].forEach(x=>document.getElementById('s1_'+x).classList.remove('active'));
  document.getElementById('s1_'+v).classList.add('active');
  drawSim1();
}

function drawSim1() {
  const canvas = document.getElementById('c1');
  const {w:W, h:H, ctx} = resizeCanvas(canvas);
  const pad = {t:20, r:30, b:48, l:58};
  const cW = W-pad.l-pad.r;
  const cH = H-pad.t-pad.b;
  const STEPS = 300;
  const toX = t => pad.l + (t/TIMELINE_1)*cW;
  const toY = v => pad.t + (1-v)*cH;
