// ════════════════════════════════════════

const YEAR_START   = 2000;   // chart start
const YEAR_IGNITION= 2037;   // T+0: cascade locks — IPCC TAR runaway carbon dynamics ignition
const YEAR_RELEASE = 2041;   // T+4: optimal planetary intervention — before ocean autonomous destabilization
const YEAR_END     = 2152;   // T+115: winter end + small buffer (111yr from 2041)
const CHART_SPAN   = YEAR_END - YEAR_START; // 152 years total
const WINTER_DUR   = 111;    // calibrated from Yellowstone geological record
const CASCADE_RATE = 5/13;   // °C per year post-ignition (Schaller & Wright 2013)
const PEAK_TEMP_DROP = 11.5; // °C peak volcanic winter drop (hot planet amplified)
const FLOOR_TEMP_DROP = 3.0; // °C sustained ice-albedo floor

const S1 = {
  accel: 1.0, supp: 78, wint: 1.0, prep: 0.1,
  view: 'all',
  // Fixed anchored values — not sliders for these
  rel: YEAR_RELEASE - YEAR_IGNITION,   // = 4yr post ignition
  lag: 8.0                              // public detectability lag post-ignition
};

function s1_cascade(yr) {
  // t = years since ignition
  const t = yr - YEAR_IGNITION;
  if(t <= 0) return 0;
  // Pre-ignition: slow background accumulation since 2000 (existing climate change)
  const preWarm = clamp((yr - YEAR_START) / (YEAR_IGNITION - YEAR_START) * 0.18, 0, 0.18);
  // Post-ignition: +5°C/13yr sigmoid cascade
  const cascadeProgress = clamp(sigmoid(t/13*S1.accel, 8, 0.5)*1.02, 0, 1);
  return preWarm + cascadeProgress * (1 - preWarm);
}

function s1_yellowstonePressure(yr) {
  const t = yr - YEAR_IGNITION;
  const rel = YEAR_RELEASE - YEAR_IGNITION; // 4
  if(yr < YEAR_IGNITION) {
    // Suppressed accumulation 2000-2037
    const nat = clamp(0.22 + (yr-YEAR_START)/37*0.55, 0, 0.95);
    const sup = nat*(1-(S1.supp/100)*0.82);
    const noise = Math.sin((yr-YEAR_START)*4.1)*0.012+Math.sin((yr-YEAR_START)*9.3)*0.006;
    return clamp(sup+noise, 0.02, 0.95);
  }
  if(yr < YEAR_RELEASE) {
    // Post-ignition, pre-release: still suppressed, minor pressure rise
    const base = clamp(0.75 + t*0.04, 0, 0.92);
    return clamp(base*(1-(S1.supp/100)*0.4), 0.1, 0.95);
  }
  // Post-release eruption curve
  const p = yr - YEAR_RELEASE;
  const spike = Math.exp(-p*0.5)*0.98;
  const ice   = 0.35*Math.exp(-p/45)*(p>2?1:p/2);
  return clamp(spike+ice, 0, 1);
}

function s1_tempAnomaly(yr) {
  const t = yr - YEAR_IGNITION;
  const w = S1.wint;
  // Pre-ignition: existing +1.4°C baseline warming trend
  if(yr < YEAR_IGNITION) {
    return 1.4 * (yr - YEAR_START) / (YEAR_IGNITION - YEAR_START);
  }
  if(yr < YEAR_RELEASE) {
    // Post-ignition pre-release: +5°C/13yr cascade
    return 1.4 + t * CASCADE_RATE * S1.accel;
  }
  const p = yr - YEAR_RELEASE;
  const cascadeWarmth = 1.4 + (YEAR_RELEASE-YEAR_IGNITION)*CASCADE_RATE; // ~2.9°C at release
  const aerosol = PEAK_TEMP_DROP*w*Math.exp(-p/6)*Math.min(1,p/1.5);
  const iceAlbedo = FLOOR_TEMP_DROP*w*(1-Math.exp(-p/8))*Math.exp(-p/85);
  const residualCasc = cascadeWarmth*(1-w*0.92)*Math.exp(-p/20);
  return cascadeWarmth - aerosol - iceAlbedo + residualCasc;
}

function s1_surfacePop(yr) {
  const w = S1.wint;
  if(yr <= YEAR_START) return 1.0;
  if(yr < YEAR_IGNITION) {
    // Background mortality 2000-2037: slow baseline climate degradation
    const progress = (yr - YEAR_START) / (YEAR_IGNITION - YEAR_START);
    return clamp(1 - progress*0.05, 0.95, 1.0);
  }
  const t = yr - YEAR_IGNITION;
  if(yr < YEAR_RELEASE) {
    // T+0 to T+4: cascade running but not yet visible mortality at scale
    // +5°C in 13yr — discomfort starts ~T+5, so pre-release pop barely declining
    const cascadeHeat = t * CASCADE_RATE;
    return clamp(0.95 - cascadeHeat*0.015, 0.88, 0.95);
  }
