}

// Planetary health index — what matters for long-term biosphere recovery
// Driven by: temp anomaly returning to safe range, CO2 drawdown from weathering,
// ocean chemistry recovering, albedo stabilizing
function s1_planetaryHealth(yr) {
  if(yr < YEAR_RELEASE) {
    // Degrading pre-release
    const t = yr - YEAR_IGNITION;
    const preIgn = (yr - YEAR_START)/(YEAR_IGNITION - YEAR_START);
    if(yr < YEAR_IGNITION) return 1.0 - preIgn*0.15;
    return 0.85 - clamp(t*CASCADE_RATE*0.08, 0, 0.3);
  }
  const p = yr - YEAR_RELEASE;
  const temp = s1_tempAnomaly(yr);
  // Planetary health improves when temp anomaly approaches 0 and weathering sequesters CO2
  const tempRecovery = 1 - clamp(Math.abs(temp)/8, 0, 1);
