function drawSim1() {
  const canvas = document.getElementById('c1');
  const {w:W, h:H, ctx} = resizeCanvas(canvas);
  const pad = {t:24, r:24, b:52, l:58};
  const cW = W-pad.l-pad.r;
  const cH = H-pad.t-pad.b;
  const STEPS = 400;

  // Year → X pixel
  const toX = yr => pad.l + ((yr-YEAR_START)/CHART_SPAN)*cW;
  // Value 0-1 → Y pixel
  const toY = v  => pad.t + (1-clamp(v,0,1))*cH;
  // Temp anomaly → Y (scaled -15 to +8°C → 0-1)
  const toYT = c  => pad.t + (1-clamp((c+15)/23,0,1))*cH;

  ctx.clearRect(0,0,W,H);
  ctx.fillStyle='#03040a'; ctx.fillRect(0,0,W,H);

