    ctx.beginPath(); ctx.moveTo(pad.l,y); ctx.lineTo(pad.l+cW,y); ctx.stroke();
  }
  // Year grid lines every 10yr
  for(let yr=YEAR_START;yr<=YEAR_END;yr+=10){
    const x=toX(yr);
    ctx.beginPath(); ctx.moveTo(x,pad.t); ctx.lineTo(x,pad.t+cH); ctx.stroke();
  }

  // ── FOUR-SIDED BORDER (closed rectangle) ──
  ctx.strokeStyle='rgba(255,255,255,0.18)'; ctx.lineWidth=1.5;
  ctx.beginPath();
  ctx.rect(pad.l, pad.t, cW, cH);
  ctx.stroke();

  // ── AXIS LABELS ──
  ctx.fillStyle='rgba(255,255,255,0.28)'; ctx.font='9px Inconsolata'; ctx.textAlign='center';
  for(let yr=2000;yr<=YEAR_END;yr+=10){
    ctx.fillText(yr, toX(yr), pad.t+cH+16);
  }
  ctx.textAlign='right'; ctx.font='9px Inconsolata';
  for(let i=0;i<=10;i++){
