  // Axis titles
  ctx.save(); ctx.translate(12,pad.t+cH/2); ctx.rotate(-Math.PI/2);
  ctx.textAlign='center'; ctx.fillStyle='rgba(255,255,255,0.15)'; ctx.font='8px Inconsolata';
