    { yr:YEAR_RELEASE,  color:'rgba(0,170,255,0.5)',  dash:[4,3], label:'YELLOWSTONE RELEASE 2041', side:'left'  },
    { yr:YEAR_RELEASE+WINTER_DUR, color:'rgba(0,170,255,0.25)', dash:[2,5], label:'WINTER END 2152', side:'right' },
  ];
  markers.forEach(m=>{
    const x = toX(m.yr);
    if(x < pad.l || x > pad.l+cW) return;
    ctx.save();
    ctx.strokeStyle=m.color; ctx.lineWidth=1;
    ctx.setLineDash(m.dash);
    ctx.beginPath(); ctx.moveTo(x,pad.t); ctx.lineTo(x,pad.t+cH); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle=m.color.replace('0.5','0.8').replace('0.45','0.8').replace('0.25','0.6');
    ctx.font='8px Inconsolata';
    ctx.textAlign = m.side==='right' ? 'left' : 'right';
