  // Detection marker
  const detX = toX(S1.lag);
  ctx.save(); ctx.strokeStyle='rgba(212,168,67,0.4)'; ctx.lineWidth=1;
  ctx.setLineDash([5,4]); ctx.beginPath(); ctx.moveTo(detX,pad.t); ctx.lineTo(detX,pad.t+cH); ctx.stroke();
  ctx.setLineDash([]); ctx.restore();
  ctx.fillStyle='rgba(212,168,67,0.6)'; ctx.font='8px Inconsolata'; ctx.textAlign='left';
  ctx.fillText('DETECT', detX+3, pad.t+12);

  // Release marker
  const relX = toX(S1.rel);
  ctx.save(); ctx.strokeStyle='rgba(0,170,255,0.4)'; ctx.lineWidth=1;
  ctx.setLineDash([4,3]); ctx.beginPath(); ctx.moveTo(relX,pad.t); ctx.lineTo(relX,pad.t+cH); ctx.stroke();
  ctx.setLineDash([]); ctx.restore();
  ctx.fillStyle='rgba(0,170,255,0.6)'; ctx.font='8px Inconsolata'; ctx.textAlign='right';
  ctx.fillText('RELEASE', relX-3, pad.t+12);

  // Winter end marker
  const winterEnd = toX(S1.rel + WINTER_MAX*S1.wint);
  if(winterEnd < W-pad.r) {
    ctx.save(); ctx.strokeStyle='rgba(0,170,255,0.2)'; ctx.lineWidth=1;
    ctx.setLineDash([2,5]); ctx.beginPath(); ctx.moveTo(winterEnd,pad.t); ctx.lineTo(winterEnd,pad.t+cH); ctx.stroke();
    ctx.setLineDash([]); ctx.restore();
    ctx.fillStyle='rgba(0,170,255,0.3)'; ctx.font='8px Inconsolata'; ctx.textAlign='left';
    ctx.fillText('WINTER END', winterEnd+3, pad.t+24);
  }

  const pts = (fn, norm=true) => {
    const arr=[];
    for(let i=0;i<=STEPS2;i++){
      const t=i*(TIMELINE_1/STEPS2);
      const v=norm?clamp(fn(t),0,1):fn(t);
      arr.push([toX(t), norm?toY(v):toY(clamp((v+15)/30,0,1))]);
    }
    return arr;
  };

  const sv = S1.view;

  // Temperature (normalized -15 to +15°C → 0-1)
  if(sv==='all'||sv==='temp') {
    const tpts = pts(t=>s1_tempAnomaly(t),false);
    drawArea(ctx, tpts, 'rgb(100,100,200)', 0.04, W, H, pad);
    drawCurve(ctx, tpts, 'rgba(120,120,220,0.7)', null, 1.5, [3,4]);
  }

  if(sv==='all'||sv==='winter') {
    const ypts = pts(t=>s1_yellowstone(t));
    drawArea(ctx, ypts, 'rgb(0,170,255)', 0.05, W, H, pad);
    drawCurve(ctx, ypts, 'rgb(0,170,255)', 'rgb(0,170,255)', 2);
  }

  if(sv==='all'||sv==='pop') {
    const spts = pts(t=>s1_surfacePop(t));
    drawArea(ctx, spts, 'rgb(255,102,0)', 0.05, W, H, pad);
    drawCurve(ctx, spts, 'rgb(255,102,0)', null, 2);

    const ppts = pts(t=>s1_preparedPop(t));
    drawArea(ctx, ppts, 'rgb(0,255,136)', 0.06, W, H, pad);
    drawCurve(ctx, ppts, 'rgb(0,255,136)', 'rgb(0,255,136)', 2.5);
  }

  if(sv==='all'||sv==='cascade') {
    const cpts = pts(t=>s1_cascade(t));
    drawArea(ctx, cpts, 'rgb(255,34,0)', 0.06, W, H, pad);
    drawCurve(ctx, cpts, 'rgb(255,34,0)', 'rgb(255,34,0)', 2.5);
  }

  // Intersection zone highlight
  if(currentView === 'both') {
    let intersectT = null;
    for(let i=1;i<=STEPS2;i++){
      const t=i*(TIMELINE_1/STEPS2);
      const prevT=(i-1)*(TIMELINE_1/STEPS2);
      const cv=s1_cascade(t); const pv=s1_surfacePop(t);
      const cvP=s1_cascade(prevT); const pvP=s1_surfacePop(prevT);
      if(cvP>pvP&&cv<=pv||cvP<pvP&&cv>=pv){intersectT=t;break;}
    }
    if(intersectT!==null){
      const ix=toX(intersectT); const iy=toY(s1_cascade(intersectT));
      ctx.beginPath(); ctx.arc(ix,iy,6,0,Math.PI*2);
      ctx.strokeStyle='rgba(255,255,255,0.6)'; ctx.lineWidth=1.5; ctx.stroke();
      ctx.fillStyle='rgba(255,255,255,0.1)'; ctx.fill();
      ctx.fillStyle='rgba(255,255,255,0.5)'; ctx.font='9px Inconsolata'; ctx.textAlign='left';
      ctx.fillText('DECISION NODE',ix+10,iy-4);
    }
  }

  updateSim1Metrics();
}

function updateSim1Metrics() {
  const winterDur = Math.round(WINTER_MAX*S1.wint);
  const peakTemp  = (11.5*S1.wint).toFixed(1);
  const surfRel   = (s1_surfacePop(S1.rel)*100).toFixed(0);
  const surf50    = (s1_surfacePop(S1.rel+50)*100).toFixed(0);
  const prepSurv  = (s1_preparedPop(S1.rel+winterDur)*100).toFixed(0);
  const prepN     = ((S1.prep/100)*8000*(s1_preparedPop(S1.rel+winterDur))).toFixed(1);
  const arrested  = S1.wint >= 0.65;
  const silence   = Math.max(0,S1.rel-S1.lag).toFixed(1);

  document.getElementById('m1_wdur').textContent   = `${winterDur}yr`;
  document.getElementById('m1_temp').textContent   = `−${peakTemp}°C`;
  document.getElementById('m1_surf_rel').textContent = `${surfRel}%`;
  document.getElementById('m1_surf_50').textContent  = `${surf50}%`;
  document.getElementById('m1_prep_surv').textContent = `${prepSurv}%`;
  document.getElementById('m1_prep_n').textContent = `${prepN}M`;
  document.getElementById('m1_arrested').textContent = arrested ? 'YES' : 'NO';
  document.getElementById('m1_silence').textContent = `${silence}yr`;

  const log = document.getElementById('s1_log');
  const rel = S1.rel; const w = S1.wint; const lag = S1.lag;
  const wd = winterDur;
  log.innerHTML = [
    {c:'crit', t:`T+0 — CASCADE IGNITION. Feedback threshold crossed. No public signal.`},
    {c:'info', t:`T+${lag.toFixed(1)}yr — First detectable mortality signal. Narrative: climate/disease.`},
    {c:'warn', t:`T+${(rel-0.3).toFixed(1)}yr — Suppression order issued. Juxtapositional interference withdrawn.`},
    {c:'info', t:`T+${rel.toFixed(1)}yr — YELLOWSTONE RELEASE. Caldera decompression begins.`},
    {c:'crit', t:`T+${(rel+1.5).toFixed(1)}yr — Volcanic winter onset. Peak −${peakTemp}°C. Agriculture collapse northern hemisphere.`},
    {c:'crit', t:`T+${(rel+3).toFixed(1)}yr — Surface population famine event. Organized resistance non-functional.`},
    {c:'good', t:`T+${(rel+5).toFixed(1)}yr — Prepared population sealed, stable. Internal agriculture online.`},
    {c:'info', t:`T+${(rel+wd).toFixed(0)}yr — Winter end. Surface population: ${surf50}%. Prepared: ${prepSurv}%.`},
    {c:'good', t:`T+${(rel+wd+10).toFixed(0)}yr — Prepared population begins surface assessment.`},
  ].map(e=>`<div class="ev ${e.c}">${e.t}</div>`).join('');

  const vEl = document.getElementById('s1_verdict');
  if(!arrested) {
    vEl.innerHTML = `Winter severity insufficient to arrest the cascade. <span style="color:var(--cascade)">Both tracks converge on terminal.</span> Increase winter severity or advance release timing.`;
  } else {
    vEl.innerHTML = `Cascade arrested. Surface population at winter end: <span style="color:var(--pop-surface)">${surf50}%</span> of pre-event. Prepared population intact at <span style="color:var(--pop-prepared)">${prepSurv}%</span> — approximately <span style="color:var(--pop-prepared)">${prepN}M individuals</span>. Silence window between decision and public awareness: <span style="color:var(--gold)">${silence} years</span>. The plan is internally coherent.`;
  }
}

