// ════════════════════════════════════════
// SIM I — CASCADE / WINTER / SURVIVAL
// Calendar anchored: 2000=T-41, 2037=T+0, 2041=Release, 2152=Winter End
// Sources: IPCC TAR 2001 Ch19 s19.6.3.2 runaway carbon dynamics;
//          Schaller & Wright 2013 — +5°C/13yr; Yellowstone record 111yr
//          Planetary optimization: T+4 (2041) before ocean autonomous destabilization
// ════════════════════════════════════════
const YEAR_START    = 2000;
const YEAR_IGNITION = 2037;
const YEAR_RELEASE  = 2041;
const YEAR_END      = 2152;
const CHART_SPAN    = YEAR_END - YEAR_START;
const WINTER_DUR    = 111;
const CASCADE_RATE  = 5/13;
const PEAK_TEMP_DROP = 11.5;
const FLOOR_TEMP_DROP = 3.0;

const S1 = {
  accel: 1.0, supp: 78, wint: 1.0, prep: 0.1,
  rel: YEAR_RELEASE - YEAR_IGNITION,
  lag: 8.0,
  view: 'all'
};

function s1_cascade(yr) {
  const t = yr - YEAR_IGNITION;
  const preWarm = clamp((yr - YEAR_START)/(YEAR_IGNITION - YEAR_START)*0.18, 0, 0.18);
  if(t <= 0) return preWarm;
  const cascadeProgress = clamp(sigmoid(t/13*S1.accel, 8, 0.5)*1.02, 0, 1);
  return preWarm + cascadeProgress*(1-preWarm);
}

function s1_yellowstonePressure(yr) {
  if(yr < YEAR_IGNITION) {
    const nat = clamp(0.22+(yr-YEAR_START)/37*0.55, 0, 0.95);
    const sup = nat*(1-(S1.supp/100)*0.82);
    const noise = Math.sin((yr-YEAR_START)*4.1)*0.012+Math.sin((yr-YEAR_START)*9.3)*0.006;
    return clamp(sup+noise, 0.02, 0.95);
  }
  const t = yr-YEAR_IGNITION;
  if(yr < YEAR_RELEASE) {
    const base = clamp(0.75+t*0.04, 0, 0.92);
    return clamp(base*(1-(S1.supp/100)*0.4), 0.1, 0.95);
  }
  const p = yr-YEAR_RELEASE;
  return clamp(Math.exp(-p*0.5)*0.98 + 0.35*Math.exp(-p/45)*(p>2?1:p/2), 0, 1);
}

function s1_tempAnomaly(yr) {
  const w = S1.wint;
  if(yr < YEAR_IGNITION) return 1.4*(yr-YEAR_START)/(YEAR_IGNITION-YEAR_START);
  const t = yr-YEAR_IGNITION;
  if(yr < YEAR_RELEASE) return 1.4+t*CASCADE_RATE*S1.accel;
  const p = yr-YEAR_RELEASE;
  const warmAtRel = 1.4+(YEAR_RELEASE-YEAR_IGNITION)*CASCADE_RATE;
  const aerosol = PEAK_TEMP_DROP*w*Math.exp(-p/6)*Math.min(1,p/1.5);
  const iceFloor = FLOOR_TEMP_DROP*w*(1-Math.exp(-p/8))*Math.exp(-p/85);
  const residual = warmAtRel*(1-w*0.92)*Math.exp(-p/20);
  return warmAtRel - aerosol - iceFloor + residual;
}

function s1_surfacePop(yr) {
  if(yr <= YEAR_START) return 1.0;
  if(yr < YEAR_IGNITION) return clamp(1-(yr-YEAR_START)/(YEAR_IGNITION-YEAR_START)*0.05, 0.95, 1.0);
  const t = yr-YEAR_IGNITION;
  if(yr < YEAR_RELEASE) return clamp(0.95-t*CASCADE_RATE*0.015, 0.88, 0.95);
  const popAtRel = clamp(0.95-(YEAR_RELEASE-YEAR_IGNITION)*CASCADE_RATE*0.015, 0.88, 0.95);
  const p = yr-YEAR_RELEASE;
  const agriCollapse = S1.wint*0.92*(1-Math.exp(-p/2.5));
  return clamp(popAtRel*(1-agriCollapse)-(1-S1.wint*0.95)*0.08, 0.005, 1);
}

function s1_preparedPop(yr) {
  if(yr < YEAR_RELEASE) return 1.0;
  const p = yr-YEAR_RELEASE;
  return clamp(1-0.08*(1-Math.exp(-p/35)), 0.88, 1.0);
}

function s1_planetaryHealth(yr) {
  if(yr < YEAR_IGNITION) return clamp(1-(yr-YEAR_START)/(YEAR_IGNITION-YEAR_START)*0.15, 0.85, 1.0);
  const t = yr-YEAR_IGNITION;
  if(yr < YEAR_RELEASE) return clamp(0.85-t*CASCADE_RATE*0.08, 0.55, 0.85);
  const p = yr-YEAR_RELEASE;
  const temp = s1_tempAnomaly(yr);
  const tempRec = 1-clamp(Math.abs(temp)/8, 0, 1);
  const weathering = clamp(p/80, 0, 0.3);
  const ocean = clamp(p/100, 0, 0.25);
  return clamp(0.52+tempRec*0.2+weathering+ocean, 0, 1);
}

function s1param(k,v) {
  S1[k] = parseFloat(v);
  const fmt = {
    accel: v=>`${parseFloat(v).toFixed(1)}×`,
    supp:  v=>`${v}%`,
    wint:  v=>`${(parseFloat(v)*100).toFixed(0)}%`,
    prep:  v=>`${parseFloat(v).toFixed(2)}%`
  };
  if(fmt[k]) document.getElementById('v1_'+k).textContent = fmt[k](v);
  drawSim1();
}

function s1view(v) {
  S1.view = v;
  ['all','cascade','winter','pop','temp'].forEach(x=>document.getElementById('s1_'+x).classList.remove('active'));
  document.getElementById('s1_'+v).classList.add('active');
  drawSim1();
}

function drawSim1() {
  const canvas = document.getElementById('c1');
  const {w:W, h:H, ctx} = resizeCanvas(canvas);
  const pad = {t:24, r:24, b:52, l:58};
  const cW = W-pad.l-pad.r;
  const cH = H-pad.t-pad.b;
  const STEPS = 400;
  const toX = yr => pad.l + ((yr-YEAR_START)/CHART_SPAN)*cW;
  const toY = v  => pad.t + (1-clamp(v,0,1))*cH;

  ctx.clearRect(0,0,W,H);
  ctx.fillStyle='#03040a'; ctx.fillRect(0,0,W,H);

  // Grid
  ctx.strokeStyle='rgba(255,255,255,0.03)'; ctx.lineWidth=1;
  for(let i=0;i<=10;i++){
    const y=pad.t+(i/10)*cH;
    ctx.beginPath(); ctx.moveTo(pad.l,y); ctx.lineTo(pad.l+cW,y); ctx.stroke();
  }
  for(let yr=YEAR_START;yr<=YEAR_END;yr+=10){
    const x=toX(yr);
    ctx.beginPath(); ctx.moveTo(x,pad.t); ctx.lineTo(x,pad.t+cH); ctx.stroke();
  }

  // ── FOUR-SIDED CLOSED BORDER ──
  ctx.strokeStyle='rgba(255,255,255,0.2)'; ctx.lineWidth=1.5;
  ctx.beginPath();
  ctx.rect(pad.l, pad.t, cW, cH);
  ctx.stroke();

  // X axis labels
  ctx.fillStyle='rgba(255,255,255,0.28)'; ctx.font='9px Inconsolata'; ctx.textAlign='center';
  for(let yr=2000;yr<=YEAR_END;yr+=10) ctx.fillText(yr, toX(yr), pad.t+cH+16);

  // Y axis labels
  ctx.textAlign='right';
  for(let i=0;i<=10;i++) ctx.fillText(`${i*10}%`, pad.l-6, toY(i/10)+3);

  // Axis titles
  ctx.save(); ctx.translate(12,pad.t+cH/2); ctx.rotate(-Math.PI/2);
  ctx.textAlign='center'; ctx.fillStyle='rgba(255,255,255,0.15)'; ctx.font='8px Inconsolata';
  ctx.fillText('INDEX / POPULATION %', 0, 0); ctx.restore();
  ctx.textAlign='center'; ctx.fillStyle='rgba(255,255,255,0.15)'; ctx.font='8px Inconsolata';
