    {yr:YEAR_RELEASE,             color:'rgba(0,170,255,0.55)',  dash:[4,3], label:'RELEASE 2041', side:'l'},
    {yr:YEAR_RELEASE+WINTER_DUR,  color:'rgba(0,170,255,0.28)',  dash:[2,5], label:'WINTER END 2152', side:'r'},
  ];
  markers.forEach(m=>{
    const x=toX(m.yr);
    if(x<pad.l||x>pad.l+cW) return;
    ctx.save();
    ctx.strokeStyle=m.color; ctx.lineWidth=1; ctx.setLineDash(m.dash);
