  const pts = fn => {
    const arr=[];
    for(let i=0;i<=STEPS;i++){
      const yr=YEAR_START+i*(CHART_SPAN/STEPS);
      arr.push([toX(yr), toY(fn(yr))]);
    }
    return arr;
  };

  const sv = S1.view;

  if(sv==='all') {
    const ph=pts(yr=>s1_planetaryHealth(yr));
    drawArea(ctx,ph,'rgb(80,180,80)',0.04,W,H,pad);
    drawCurve(ctx,ph,'rgba(80,180,80,0.4)',null,1.5,[2,6]);
  }
  if(sv==='all'||sv==='temp') {
    // Temperature scaled: -15 to +8 → 0-1
    const tp=[];
    for(let i=0;i<=STEPS;i++){
      const yr=YEAR_START+i*(CHART_SPAN/STEPS);
      const c=s1_tempAnomaly(yr);
      tp.push([toX(yr), pad.t+(1-clamp((c+15)/23,0,1))*cH]);
    }
    drawArea(ctx,tp,'rgb(120,80,200)',0.04,W,H,pad);
    drawCurve(ctx,tp,'rgba(150,100,220,0.65)',null,1.5,[3,4]);
  }
  if(sv==='all'||sv==='winter') {
    const yp=pts(yr=>s1_yellowstonePressure(yr));
    drawArea(ctx,yp,'rgb(0,170,255)',0.05,W,H,pad);
    drawCurve(ctx,yp,'rgb(0,170,255)','rgb(0,170,255)',2);
  }
  if(sv==='all'||sv==='pop') {
    const sp=pts(yr=>s1_surfacePop(yr));
    drawArea(ctx,sp,'rgb(255,102,0)',0.06,W,H,pad);
    drawCurve(ctx,sp,'rgb(255,102,0)',null,2.2);
    const pp=pts(yr=>s1_preparedPop(yr));
    drawArea(ctx,pp,'rgb(0,255,136)',0.06,W,H,pad);
    drawCurve(ctx,pp,'rgb(0,255,136)','rgb(0,255,136)',2.5);
  }
  if(sv==='all'||sv==='cascade') {
    const cp=pts(yr=>s1_cascade(yr));
    drawArea(ctx,cp,'rgb(255,34,0)',0.07,W,H,pad);
    drawCurve(ctx,cp,'rgb(255,34,0)','rgb(255,34,0)',2.5);
  }

  updateSim1Metrics();
}

function updateSim1Metrics() {
