    {c:'crit',  t:`2041–2043 — Volcanic winter onset. Peak −${peakTemp}°C. Northern hemisphere agriculture collapses.`},
    {c:'info',  t:`~${YEAR_IGNITION+Math.round(S1.lag)} — First undeniable public mortality signal. Arrives ${Math.abs(silenceYrs)}yr after release.`},
    {c:'good',  t:`2041–2152 — Silicate weathering of Yellowstone ejecta sequesters CO₂. Cascade feedbacks arrested.`},
    {c:'teal',  t:`2152 — Winter ends. Planetary health: ${planetEnd}%. Prepared population emerges. Surface viable.`},
  ].map(e=>`<div class="ev ${e.c}">${e.t}</div>`).join('');

  document.getElementById('s1_verdict').innerHTML =
    `<span style="color:var(--winter)">2041 (T+4)</span> is the planetary optimization release point — before ocean autonomous methane hydrate destabilization. Winter arrests cascade feedbacks. Surface population at release: <span style="color:var(--pop-surface)">${surfAtRel}%</span> — winter is primary mortality, not cascade. Prepared population emerges 2152 at <span style="color:var(--pop-prepared)">${prepSurv}%</span> (~${prepN}M) onto a planet with atmospheric chemistry <span style="color:var(--pop-prepared)">recovering</span>. Planetary health index at 2152: <span style="color:var(--pop-prepared)">${planetEnd}%</span>. This is the paradise planet scenario — biosphere preserved at civilizational cost.`;
}

