    const cp=ptsFn(yr=>s1_cascade(yr));
    drawArea(ctx,cp,'rgb(255,34,0)',0.07,W,H,pad);
    drawCurve(ctx,cp,'rgb(255,34,0)','rgb(255,34,0)',2.5);
  }

  updateSim1Metrics();
}

function updateSim1Metrics() {
  const winterEnd  = YEAR_RELEASE+WINTER_DUR;
  const peakTemp   = (PEAK_TEMP_DROP*S1.wint).toFixed(1);
  const surfAtRel  = (s1_surfacePop(YEAR_RELEASE)*100).toFixed(0);
  const surf2100   = (s1_surfacePop(2100)*100).toFixed(1);
  const prepSurv   = (s1_preparedPop(winterEnd)*100).toFixed(0);
  const prepN      = ((S1.prep/100)*8000*s1_preparedPop(winterEnd)).toFixed(1);
  const arrested   = S1.wint >= 0.65;
  const silenceYrs = Math.round(YEAR_RELEASE-(YEAR_IGNITION+S1.lag));
  const planetEnd  = (s1_planetaryHealth(YEAR_END)*100).toFixed(0);

  document.getElementById('m1_wdur').textContent     = `${WINTER_DUR}yr`;
  document.getElementById('m1_temp').textContent     = `-${peakTemp}C`;
  document.getElementById('m1_surf_rel').textContent = `${surfAtRel}%`;
  document.getElementById('m1_surf_50').textContent  = `${surf2100}%`;
  document.getElementById('m1_prep_surv').textContent= `${prepSurv}%`;
  document.getElementById('m1_prep_n').textContent   = `${prepN}M`;
  document.getElementById('m1_arrested').textContent = arrested?'YES':'NO';
  document.getElementById('m1_silence').textContent  = silenceYrs>=0?`${silenceYrs}yr before detect`:`${Math.abs(silenceYrs)}yr after detect`;

  document.getElementById('s1_log').innerHTML = [
    {c:'info', t:`2000 - Chart start. Background +1.4C warming trend underway.`},
    {c:'warn', t:`2015 - Paris Agreement. Suppression of Yellowstone active. Cascade building silently.`},
    {c:'crit', t:`2037 - CASCADE IGNITION. IPCC TAR 2001 runaway carbon dynamics locked. +5C/13yr trajectory.`},
    {c:'warn', t:`2041 - YELLOWSTONE RELEASE (T+4). Optimal planetary window. Ocean not yet autonomous.`},
    {c:'crit', t:`2041-2043 - Volcanic winter onset. Peak -${peakTemp}C. Northern hemisphere agriculture collapses.`},
    {c:'info', t:`~${YEAR_IGNITION+Math.round(S1.lag)} - First undeniable public mortality signal.`},
    {c:'good', t:`2041-2152 - Silicate weathering sequesters CO2. Cascade feedbacks arrested.`},
    {c:'teal', t:`2152 - Winter ends. Planetary health: ${planetEnd}%. Prepared population emerges.`},
  ].map(e=>`<div class="ev ${e.c}">${e.t}</div>`).join('');

  document.getElementById('s1_verdict').innerHTML =
    `Release at 2041 (T+4) is the planetary optimization point. Winter arrests cascade before ocean autonomous methane destabilization. Surface pop at release: ${surfAtRel}% - winter is primary mortality event. Prepared population emerges 2152 at ${prepSurv}% (~${prepN}M). Planetary health at 2152: ${planetEnd}%. Biosphere preserved.`;
}

'''

# Lines 782-1011 (0-indexed: 781 to 1010) are the old functions
# Replace them
new_lines = lines[:781] + [new_functions + '\n'] + lines[1010:]

with open('/mnt/user-data/outputs/terminal_horizon_v2.html', 'w') as f:
    f.writelines(new_lines)

print(f"Done. New file has {len(new_lines)} lines")
PYEOF

