<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>TERMINAL HORIZON — THREE SIMULATION SUITE</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700;900&family=Inconsolata:wght@300;400;600&display=swap');
:root {
  --bg:#03040a; --panel:#070810; --border:#12142a; --border-bright:#1e2245;
  --cascade:#ff2200; --winter:#00aaff; --pop-surface:#ff6600; --pop-prepared:#00ff88;
  --braided:#00ffcc; --nonbraided:#ff4466; --gold:#d4a843;
  --text:#b8bcd4; --dim:#444466; --bright:#e8ecff;
  --glow-red:0 0 20px rgba(255,34,0,0.5); --glow-blue:0 0 20px rgba(0,170,255,0.5);
  --glow-green:0 0 20px rgba(0,255,136,0.5); --glow-teal:0 0 20px rgba(0,255,204,0.5);
  --glow-pink:0 0 20px rgba(255,68,102,0.5); --glow-gold:0 0 20px rgba(212,168,67,0.4);
}
*{margin:0;padding:0;box-sizing:border-box;}
html{font-size:16px;}
body{background:var(--bg);color:var(--text);font-family:'Inconsolata',monospace;min-height:100vh;overflow-x:hidden;-webkit-text-size-adjust:100%;}
body::before{content:'';position:fixed;inset:0;background:radial-gradient(ellipse 60% 40% at 20% 20%,rgba(255,34,0,0.03) 0%,transparent 70%),radial-gradient(ellipse 50% 30% at 80% 80%,rgba(0,170,255,0.03) 0%,transparent 70%),radial-gradient(ellipse 40% 60% at 50% 50%,rgba(0,255,204,0.02) 0%,transparent 70%);pointer-events:none;z-index:0;}
.scanlines{position:fixed;inset:0;background:repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(0,0,0,0.05) 3px,rgba(0,0,0,0.05) 4px);pointer-events:none;z-index:1000;}
.wrapper{position:relative;z-index:1;}
header{padding:16px 16px 14px;border-bottom:1px solid var(--border-bright);position:relative;overflow:hidden;}
header::after{content:'';position:absolute;bottom:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent 0%,var(--cascade) 30%,var(--braided) 70%,transparent 100%);opacity:0.5;}
.hdr{display:flex;flex-direction:column;gap:8px;}
@media(min-width:900px){.hdr{flex-direction:row;justify-content:space-between;align-items:start;} header{padding:24px 40px 18px;}}
h1{font-family:'Orbitron',monospace;font-weight:900;font-size:clamp(16px,5vw,32px);letter-spacing:clamp(1px,0.5vw,4px);color:var(--bright);line-height:1.1;}
h1 em{color:var(--cascade);font-style:normal;text-shadow:var(--glow-red);}
h1 span{color:var(--braided);text-shadow:var(--glow-teal);}
.subtitle{font-size:clamp(8px,2vw,9px);letter-spacing:1.5px;color:var(--dim);text-transform:uppercase;margin-top:3px;line-height:1.5;}
.hdr-meta{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:9px;color:var(--dim);}
.hdr-meta .live{color:var(--cascade);animation:pulse 1.6s infinite;}
.hdr-meta .author{color:var(--gold);letter-spacing:1.5px;}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.2}}
.tab-nav{display:flex;border-bottom:1px solid var(--border-bright);background:rgba(0,0,0,0.3);overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;}
.tab-nav::-webkit-scrollbar{display:none;}
.tab{flex-shrink:0;padding:12px 14px;font-family:'Orbitron',monospace;font-size:clamp(8px,2vw,9px);font-weight:700;letter-spacing:1.5px;color:var(--dim);cursor:pointer;border-bottom:2px solid transparent;transition:all 0.2s;text-transform:uppercase;white-space:nowrap;-webkit-tap-highlight-color:transparent;position:relative;}
.tab:hover{color:var(--text);}
.tab.active{color:var(--bright);border-bottom-color:var(--gold);}
.tab.active::after{content:'';position:absolute;bottom:-2px;left:0;right:0;height:2px;background:var(--gold);box-shadow:var(--glow-gold);}
.sim-panel{display:none;padding:12px 12px 32px;}
.sim-panel.active{display:block;}
@media(min-width:900px){.sim-panel{padding:20px 40px 40px;}}
.sim-layout{display:flex;flex-direction:column;gap:14px;}
@media(min-width:900px){.sim-layout{display:grid;grid-template-columns:1fr 300px;gap:22px;height:calc(100vh - 190px);min-height:520px;}}
.chart-col{display:flex;flex-direction:column;gap:10px;}
.chart-label{font-family:'Orbitron',monospace;font-size:clamp(8px,2vw,9px);letter-spacing:1.5px;color:var(--dim);text-transform:uppercase;line-height:1.4;}
.chart-scroll{width:100%;overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;scrollbar-width:thin;scrollbar-color:var(--border-bright) transparent;}
.chart-scroll::-webkit-scrollbar{height:3px;}
.chart-scroll::-webkit-scrollbar-thumb{background:var(--border-bright);}
.chart-wrap{position:relative;width:620px;min-width:620px;height:260px;}
@media(min-width:900px){.chart-scroll{overflow-x:visible;}.chart-wrap{width:100%;min-width:0;flex:1;height:auto;min-height:300px;}}
canvas{display:block;width:100%;height:100%;}
.swipe-hint{font-size:9px;color:var(--dim);letter-spacing:2px;text-align:center;padding:3px 0;opacity:0.5;}
@media(min-width:900px){.swipe-hint{display:none;}}
.view-btns{display:flex;gap:5px;flex-wrap:wrap;}
.sidebar-col{display:flex;flex-direction:column;gap:12px;}
@media(min-width:900px){.sidebar-col{overflow-y:auto;}}
.panel{background:var(--panel);border:1px solid var(--border);padding:12px;position:relative;}
.panel::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--border-bright),transparent);}
.panel-title{font-family:'Orbitron',monospace;font-size:clamp(8px,2vw,9px);letter-spacing:2px;color:var(--dim);text-transform:uppercase;margin-bottom:10px;padding-bottom:7px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;cursor:pointer;-webkit-tap-highlight-color:transparent;user-select:none;}
.panel-title::after{content:'▾';font-size:10px;color:var(--dim);transition:transform 0.2s;}
.panel.collapsed .panel-title::after{transform:rotate(-90deg);}
.panel-body{overflow:hidden;}
.panel.collapsed .panel-body{max-height:0!important;}
.ctrl{margin-bottom:12px;}
.ctrl-label{font-size:9px;color:var(--dim);letter-spacing:1px;display:flex;justify-content:space-between;margin-bottom:7px;}
.ctrl-label span{color:var(--text);font-size:10px;}
input[type=range]{-webkit-appearance:none;width:100%;height:4px;background:var(--border-bright);outline:none;border-radius:2px;cursor:pointer;}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:20px;height:20px;background:var(--gold);cursor:pointer;border-radius:2px;box-shadow:0 0 8px rgba(212,168,67,0.5);}
.metrics{display:grid;grid-template-columns:1fr 1fr;gap:6px;}
.metric{background:rgba(255,255,255,0.02);border:1px solid var(--border);padding:8px 10px;}
.metric-label{font-size:8px;color:var(--dim);letter-spacing:0.5px;text-transform:uppercase;margin-bottom:3px;line-height:1.3;}
.metric-value{font-family:'Orbitron',monospace;font-size:clamp(12px,3.5vw,14px);font-weight:700;}
.mv-red{color:var(--cascade);text-shadow:var(--glow-red);}
.mv-blue{color:var(--winter);text-shadow:var(--glow-blue);}
.mv-green{color:var(--pop-prepared);text-shadow:var(--glow-green);}
.mv-teal{color:var(--braided);text-shadow:var(--glow-teal);}
.mv-pink{color:var(--nonbraided);text-shadow:var(--glow-pink);}
