.legend-item{display:flex;align-items:center;gap:8px;font-size:clamp(9px,2.2vw,10px);margin-bottom:2px;}
.leg-line{width:20px;height:2px;flex-shrink:0;}
.leg-dash{width:20px;height:0;flex-shrink:0;border-top:2px dashed currentColor;}
.event-log{font-size:clamp(9px,2vw,9px);line-height:1.9;max-height:150px;overflow-y:auto;}
.ev{padding:2px 0;border-bottom:1px solid rgba(255,255,255,0.03);}
.ev.crit{color:var(--cascade);} .ev.warn{color:var(--gold);} .ev.info{color:var(--winter);}
.ev.good{color:var(--pop-prepared);} .ev.teal{color:var(--braided);} .ev.pink{color:var(--nonbraided);}
.verdict{background:rgba(212,168,67,0.04);border:1px solid rgba(212,168,67,0.15);padding:12px;font-size:clamp(9px,2vw,10px);line-height:1.8;}
.verdict.nb{background:rgba(255,68,102,0.04);border-color:rgba(255,68,102,0.2);}
.verdict.br{background:rgba(0,255,204,0.04);border-color:rgba(0,255,204,0.2);}
.v-label{font-family:'Orbitron',monospace;font-size:clamp(8px,1.8vw,9px);letter-spacing:2px;text-transform:uppercase;margin-bottom:6px;}
.v-label.nb{color:var(--nonbraided);}
.v-label.br{color:var(--braided);}
.v-label.gold{color:var(--gold);}
.btn{background:transparent;border:1px solid var(--border-bright);color:var(--dim);font-family:'Inconsolata',monospace;font-size:clamp(9px,2vw,10px);letter-spacing:1.5px;padding:8px 10px;cursor:pointer;text-transform:uppercase;transition:all 0.15s;-webkit-tap-highlight-color:transparent;touch-action:manipulation;}
.btn:hover,.btn:active{border-color:var(--gold);color:var(--gold);}
.btn.active{border-color:var(--gold);color:var(--gold);background:rgba(212,168,67,0.08);}
.age-bar-wrap{margin-top:8px;}
.age-bar-label{font-size:8px;color:var(--dim);letter-spacing:1px;margin-bottom:4px;}
.age-bar{height:8px;background:var(--border);border-radius:2px;overflow:hidden;margin-bottom:3px;}
.age-fill-nb{height:100%;background:linear-gradient(90deg,var(--nonbraided),rgba(255,68,102,0.3));transition:width 0.3s;}
.age-fill-br{height:100%;background:linear-gradient(90deg,var(--braided),rgba(0,255,204,0.3));transition:width 0.3s;}
::-webkit-scrollbar{width:3px;}
::-webkit-scrollbar-track{background:transparent;}
::-webkit-scrollbar-thumb{background:var(--border-bright);}
</style>
</head>
