  drawBorder(ctx,W,H,pad);
  const toX=yr=>pad.l+((yr-BR_START)/BR_SPAN)*cW;
  const toY=v=>pad.t+(1-clamp(v/2.0,0,1))*cH; // scaled 0-200% to show post-human
  ctx.fillStyle='rgba(255,255,255,0.25)';ctx.font='9px Inconsolata';ctx.textAlign='center';
  for(let yr=BR_START;yr<=BR_END;yr+=25)ctx.fillText(yr,toX(yr),pad.t+cH+16);
