.panel-title{font-family:'Orbitron',monospace;font-size:clamp(8px,2vw,9px);letter-spacing:2px;color:var(--dim);text-transform:uppercase;margin-bottom:10px;padding-bottom:7px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;cursor:pointer;-webkit-tap-highlight-color:transparent;user-select:none;}
