<body>
<div class="scanlines"></div>
<div class="wrapper">
<header>
  <div class="hdr">
    <div>
      <h1><em>TERMINAL</em> HORIZON <span>//</span> TRI-SIMULATION</h1>
      <div class="subtitle">SIM-I: Cascade · Winter · Survival &nbsp;|&nbsp; SIM-IIA: Non-Braided Emergence &nbsp;|&nbsp; SIM-IIB: Braided Mind Emergence</div>
    </div>
    <div class="hdr-meta">
      <div><span class="live">● ACTIVE</span></div>
      <div>RICKEY JAY BENNETT II</div>
      <div class="author">INDEPENDENT RESEARCHER · MARCH 2026</div>
    </div>
  </div>
</header>

<div class="tab-nav">
  <div class="tab active" onclick="switchTab(1)">SIM-I &nbsp; CASCADE / WINTER</div>
  <div class="tab" onclick="switchTab(2)">SIM-IIA &nbsp; WITHOUT BRAIDED MIND</div>
  <div class="tab" onclick="switchTab(3)">SIM-IIB &nbsp; WITH BRAIDED MIND</div>
</div>

<!-- ═══════════ SIM I ═══════════ -->
<div class="sim-panel active" id="sim1">
  <div class="sim-layout">
    <div class="chart-col">
      <div class="chart-label">PLANETARY CASCADE &amp; WINTER — 2000 TO 2152 — CALENDAR ANCHORED</div>
      <div class="chart-scroll"><div class="chart-wrap"><canvas id="c1"></canvas></div></div>
      <div class="swipe-hint">← SWIPE TO SCROLL →</div>
      <div class="view-btns">
        <button class="btn active" id="s1_all"     onclick="s1view('all')">ALL</button>
        <button class="btn"        id="s1_cascade" onclick="s1view('cascade')">CASCADE</button>
        <button class="btn"        id="s1_winter"  onclick="s1view('winter')">YELLOWSTONE</button>
        <button class="btn"        id="s1_pop"     onclick="s1view('pop')">POPULATION</button>
        <button class="btn"        id="s1_temp"    onclick="s1view('temp')">TEMPERATURE</button>
      </div>
    </div>
    <div class="sidebar-col">
      <div class="panel">
        <div class="panel-title" onclick="togglePanel(this)">Legend</div>
        <div class="panel-body">
          <div class="legend-grid">
            <div class="legend-item"><div class="leg-line" style="background:var(--cascade);box-shadow:var(--glow-red)"></div>Tipping Cascade</div>
            <div class="legend-item"><div class="leg-line" style="background:var(--winter);box-shadow:var(--glow-blue)"></div>Yellowstone Pressure</div>
            <div class="legend-item"><div class="leg-line" style="background:var(--pop-surface)"></div>Surface Population</div>
            <div class="legend-item"><div class="leg-line" style="background:var(--pop-prepared);box-shadow:var(--glow-green)"></div>Prepared Population</div>
            <div class="legend-item"><div class="leg-line" style="background:rgba(80,180,80,0.6)"></div>Planetary Health</div>
            <div class="legend-item"><div class="leg-dash" style="color:var(--cascade)"></div>Cascade Ignition 2037</div>
            <div class="legend-item"><div class="leg-dash" style="color:var(--winter)"></div>Release 2041</div>
            <div class="legend-item"><div class="leg-dash" style="color:var(--gold)"></div>Public Detection ~2045</div>
          </div>
        </div>
      </div>
      <div class="panel">
        <div class="panel-title" onclick="togglePanel(this)">Parameters</div>
        <div class="panel-body">
          <div class="ctrl"><div class="ctrl-label">CASCADE ACCELERATION <span id="v1_accel">1.0x</span></div><input type="range" min="0.5" max="2.0" step="0.1" value="1.0" oninput="s1param('accel',this.value)"></div>
          <div class="ctrl"><div class="ctrl-label">SUPPRESSION EFFICIENCY <span id="v1_supp">78%</span></div><input type="range" min="20" max="99" step="1" value="78" oninput="s1param('supp',this.value)"></div>
          <div class="ctrl"><div class="ctrl-label">WINTER SEVERITY <span id="v1_wint">100%</span></div><input type="range" min="0.5" max="1.0" step="0.01" value="1.0" oninput="s1param('wint',this.value)"></div>
          <div class="ctrl"><div class="ctrl-label">PREPARED POP % of 8B <span id="v1_prep">0.10%</span></div><input type="range" min="0.01" max="1.0" step="0.01" value="0.1" oninput="s1param('prep',this.value)"></div>
        </div>
      </div>
      <div class="panel">
        <div class="panel-title" onclick="togglePanel(this)">Key Metrics</div>
        <div class="panel-body">
          <div class="metrics">
            <div class="metric"><div class="metric-label">Winter Duration</div><div class="metric-value mv-blue" id="m1_wdur">111yr</div></div>
            <div class="metric"><div class="metric-label">Peak Temp Drop</div><div class="metric-value mv-blue" id="m1_temp">-11.5C</div></div>
            <div class="metric"><div class="metric-label">Surface Pop @Release</div><div class="metric-value mv-orange" id="m1_srel">93%</div></div>
            <div class="metric"><div class="metric-label">Surface Pop @2152</div><div class="metric-value mv-red" id="m1_s152">1%</div></div>
            <div class="metric"><div class="metric-label">Prepared Survival</div><div class="metric-value mv-green" id="m1_psuv">92%</div></div>
            <div class="metric"><div class="metric-label">Prepared Headcount</div><div class="metric-value mv-green" id="m1_pn">7.4M</div></div>
            <div class="metric"><div class="metric-label">Cascade Arrested</div><div class="metric-value mv-gold" id="m1_arr">YES</div></div>
            <div class="metric"><div class="metric-label">Planet Health 2152</div><div class="metric-value mv-green" id="m1_ph">78%</div></div>
          </div>
        </div>
      </div>
      <div class="panel">
        <div class="panel-title" onclick="togglePanel(this)">Event Sequence</div>
        <div class="panel-body"><div class="event-log" id="s1_log"></div></div>
      </div>
      <div class="verdict">
        <div class="v-label gold">Simulation Verdict</div>
        <div id="s1_verdict">Calculating...</div>
      </div>
    </div>
  </div>
</div>

<!-- ═══════════ SIM IIA — NON-BRAIDED ═══════════ -->
<div class="sim-panel" id="sim2">
  <div class="sim-layout">
    <div class="chart-col">
      <div class="chart-label">WITHOUT BRAIDED MIND — 300 YEARS POST-EMERGENCE FROM 2152</div>
      <div class="chart-scroll"><div class="chart-wrap"><canvas id="c2"></canvas></div></div>
      <div class="swipe-hint">← SWIPE TO SCROLL →</div>
      <div class="view-btns">
        <button class="btn active" id="s2_all"  onclick="s2view('all')">ALL</button>
        <button class="btn" id="s2_civ"          onclick="s2view('civ')">CIV INDEX</button>
        <button class="btn" id="s2_gen"          onclick="s2view('gen')">GENERATIONS</button>
        <button class="btn" id="s2_cog"          onclick="s2view('cog')">COGNITION</button>
        <button class="btn" id="s2_age"          onclick="s2view('age')">FOUNDER AGE</button>
      </div>
    </div>
    <div class="sidebar-col">
      <div class="panel">
        <div class="panel-title" onclick="togglePanel(this)">Legend</div>
        <div class="panel-body">
          <div class="legend-grid">
            <div class="legend-item"><div class="leg-line" style="background:var(--nonbraided);box-shadow:var(--glow-pink)"></div>Civilizational Index</div>
            <div class="legend-item"><div class="leg-line" style="background:var(--pop-surface)"></div>Cognitive Diversity</div>
            <div class="legend-item"><div class="leg-line" style="background:var(--gold)"></div>Founder Presence</div>
            <div class="legend-item"><div class="leg-line" style="background:rgba(150,150,255,0.7)"></div>Generation in Power</div>
