<script>
// ═══════════════════════════════════════════
// SHARED UTILITIES
// ═══════════════════════════════════════════
function sigmoid(x,slope,mid){return 1/(1+Math.exp(-slope*(x-mid)));}
function clamp(v,lo,hi){return Math.max(lo,Math.min(hi,v));}

function resizeCanvas(canvas){
  const wrap=canvas.parentElement;
  const dpr=window.devicePixelRatio||1;
  const w=wrap.offsetWidth, h=wrap.offsetHeight;
  canvas.width=w*dpr; canvas.height=h*dpr;
  canvas.style.width=w+'px'; canvas.style.height=h+'px';
  const ctx=canvas.getContext('2d');
  ctx.scale(dpr,dpr);
  return{w,h,ctx};
}

function drawBorder(ctx,W,H,pad){
  ctx.strokeStyle='rgba(255,255,255,0.2)'; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.rect(pad.l,pad.t,W-pad.l-pad.r,H-pad.t-pad.b); ctx.stroke();
}

function drawGridLines(ctx,W,H,pad,xSteps,ySteps){
  ctx.strokeStyle='rgba(255,255,255,0.03)'; ctx.lineWidth=1;
  const cW=W-pad.l-pad.r, cH=H-pad.t-pad.b;
  for(let i=0;i<=ySteps;i++){const y=pad.t+(i/ySteps)*cH;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(pad.l+cW,y);ctx.stroke();}
  for(let i=0;i<=xSteps;i++){const x=pad.l+(i/xSteps)*cW;ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+cH);ctx.stroke();}
}

function drawCurve(ctx,pts,color,glow,lw=2,dash=[]){
  ctx.save(); ctx.beginPath(); ctx.strokeStyle=color; ctx.lineWidth=lw;
  ctx.shadowColor=glow||color; ctx.shadowBlur=glow?10:0;
  if(dash.length)ctx.setLineDash(dash);
  pts.forEach((p,i)=>i===0?ctx.moveTo(p[0],p[1]):ctx.lineTo(p[0],p[1]));
  ctx.stroke(); ctx.restore();
}

function drawArea(ctx,pts,color,alpha,H,pad){
  ctx.save(); ctx.beginPath();
  ctx.moveTo(pts[0][0],H-pad.b);
  pts.forEach(p=>ctx.lineTo(p[0],p[1]));
  ctx.lineTo(pts[pts.length-1][0],H-pad.b);
  ctx.closePath();
  ctx.fillStyle=color; ctx.globalAlpha=alpha; ctx.fill(); ctx.restore();
}

function vmarker(ctx,x,top,bot,color,dash,label,side){
  ctx.save(); ctx.strokeStyle=color; ctx.lineWidth=1; ctx.setLineDash(dash);
  ctx.beginPath(); ctx.moveTo(x,top); ctx.lineTo(x,bot); ctx.stroke(); ctx.setLineDash([]);
  if(label){
    ctx.fillStyle=color.replace(/[\d.]+\)$/,'0.85)');
    ctx.font='8px Inconsolata'; ctx.textAlign=side==='r'?'left':'right';
    ctx.fillText(label,side==='r'?x+3:x-3,top+14);
  }
  ctx.restore();
}

function togglePanel(titleEl){
  const panel=titleEl.parentElement, body=panel.querySelector('.panel-body');
  if(!body)return;
  if(panel.classList.contains('collapsed')){
    panel.classList.remove('collapsed'); body.style.maxHeight=body.scrollHeight+'px';
    setTimeout(()=>body.style.maxHeight='none',300);
  } else {
    body.style.maxHeight=body.scrollHeight+'px';
    requestAnimationFrame(()=>{body.style.maxHeight='0';panel.classList.add('collapsed');});
  }
}
document.querySelectorAll('.panel-body').forEach(b=>b.style.maxHeight='none');

// ═══════════════════════════════════════════
// SIM I — CASCADE / WINTER / SURVIVAL
// ═══════════════════════════════════════════
const YS=2000,YI=2037,YR=2041,YE=2152,YSPAN=152;
const WD=111,CR=5/13,PTD=11.5,FTD=3.0;
const S1={accel:1.0,supp:78,wint:1.0,prep:0.1,lag:8.0,view:'all'};

function s1c(yr){
  const t=yr-YI, pre=clamp((yr-YS)/(YI-YS)*0.18,0,0.18);
  if(t<=0)return pre;
  return pre+clamp(sigmoid(t/13*S1.accel,8,0.5)*1.02,0,1)*(1-pre);
}
function s1yp(yr){
  if(yr<YI){const nat=clamp(0.22+(yr-YS)/37*0.55,0,0.95),sup=nat*(1-(S1.supp/100)*0.82),noise=Math.sin((yr-YS)*4.1)*0.012+Math.sin((yr-YS)*9.3)*0.006;return clamp(sup+noise,0.02,0.95);}
  const t=yr-YI;
  if(yr<YR){return clamp((0.75+t*0.04)*(1-(S1.supp/100)*0.4),0.1,0.95);}
  const p=yr-YR;
  return clamp(Math.exp(-p*0.5)*0.98+0.35*Math.exp(-p/45)*(p>2?1:p/2),0,1);
}
function s1ta(yr){
  const w=S1.wint;
  if(yr<YI)return 1.4*(yr-YS)/(YI-YS);
  const t=yr-YI;
  if(yr<YR)return 1.4+t*CR*S1.accel;
  const p=yr-YR,war=1.4+(YR-YI)*CR;
  return war-PTD*w*Math.exp(-p/6)*Math.min(1,p/1.5)-FTD*w*(1-Math.exp(-p/8))*Math.exp(-p/85)+war*(1-w*0.92)*Math.exp(-p/20);
}
function s1sp(yr){
  if(yr<=YS)return 1.0;
  if(yr<YI)return clamp(1-(yr-YS)/(YI-YS)*0.05,0.95,1.0);
  const t=yr-YI;
  if(yr<YR)return clamp(0.95-t*CR*0.015,0.88,0.95);
  const par=clamp(0.95-(YR-YI)*CR*0.015,0.88,0.95),p=yr-YR;
  return clamp(par*(1-S1.wint*0.92*(1-Math.exp(-p/2.5)))-(1-S1.wint*0.95)*0.08,0.005,1);
}
function s1pp(yr){if(yr<YR)return 1.0;const p=yr-YR;return clamp(1-0.08*(1-Math.exp(-p/35)),0.88,1.0);}
function s1ph(yr){
  if(yr<YI)return clamp(1-(yr-YS)/(YI-YS)*0.15,0.85,1.0);
  if(yr<YR){const t=yr-YI;return clamp(0.85-t*CR*0.08,0.55,0.85);}
  const p=yr-YR,temp=s1ta(yr);
  return clamp(0.52+(1-clamp(Math.abs(temp)/8,0,1))*0.2+clamp(p/80,0,0.3)+clamp(p/100,0,0.25),0,1);
}

function s1param(k,v){S1[k]=parseFloat(v);const f={accel:v=>`${parseFloat(v).toFixed(1)}x`,supp:v=>`${v}%`,wint:v=>`${(parseFloat(v)*100).toFixed(0)}%`,prep:v=>`${parseFloat(v).toFixed(2)}%`};if(f[k])document.getElementById('v1_'+k).textContent=f[k](v);drawSim1();}
function s1view(v){S1.view=v;['all','cascade','winter','pop','temp'].forEach(x=>document.getElementById('s1_'+x).classList.remove('active'));document.getElementById('s1_'+v).classList.add('active');drawSim1();}

function drawSim1(){
  const cv=document.getElementById('c1');
  const{w:W,h:H,ctx}=resizeCanvas(cv);
  const pad={t:24,r:24,b:50,l:56};
  const cW=W-pad.l-pad.r,cH=H-pad.t-pad.b;
  ctx.clearRect(0,0,W,H);ctx.fillStyle='#03040a';ctx.fillRect(0,0,W,H);
  drawGridLines(ctx,W,H,pad,15,10);
  drawBorder(ctx,W,H,pad);
  const toX=yr=>pad.l+((yr-YS)/YSPAN)*cW;
  const toY=v=>pad.t+(1-clamp(v,0,1))*cH;
  ctx.fillStyle='rgba(255,255,255,0.25)';ctx.font='9px Inconsolata';ctx.textAlign='center';
  for(let yr=2000;yr<=YE;yr+=10)ctx.fillText(yr,toX(yr),pad.t+cH+16);
  ctx.textAlign='right';for(let i=0;i<=10;i++)ctx.fillText(`${i*10}%`,pad.l-5,toY(i/10)+3);
  ctx.save();ctx.translate(12,pad.t+cH/2);ctx.rotate(-Math.PI/2);ctx.textAlign='center';ctx.fillStyle='rgba(255,255,255,0.15)';ctx.font='8px Inconsolata';ctx.fillText('INDEX / POPULATION %',0,0);ctx.restore();
  ctx.textAlign='center';ctx.fillStyle='rgba(255,255,255,0.15)';ctx.font='8px Inconsolata';ctx.fillText('CALENDAR YEAR',pad.l+cW/2,H-8);
  const mkrs=[
    {yr:YI,c:'rgba(255,34,0,0.55)',d:[5,4],l:'CASCADE 2037',s:'r'},
    {yr:YI+S1.lag,c:'rgba(212,168,67,0.5)',d:[4,4],l:'DETECTION ~2045',s:'r'},
    {yr:YR,c:'rgba(0,170,255,0.55)',d:[4,3],l:'RELEASE 2041',s:'l'},
    {yr:YR+WD,c:'rgba(0,170,255,0.28)',d:[2,5],l:'WINTER END 2152',s:'r'},
  ];
  mkrs.forEach(m=>{const x=toX(m.yr);if(x>=pad.l&&x<=pad.l+cW)vmarker(ctx,x,pad.t,pad.t+cH,m.c,m.d,m.l,m.s);});
  const STEPS=400;
  const pts=fn=>{const a=[];for(let i=0;i<=STEPS;i++){const yr=YS+i*(YSPAN/STEPS);a.push([toX(yr),toY(fn(yr))]);}return a;};
  const sv=S1.view;
  if(sv==='all'){const ph=pts(yr=>s1ph(yr));drawArea(ctx,ph,'rgb(80,180,80)',0.04,H,pad);drawCurve(ctx,ph,'rgba(80,180,80,0.4)',null,1.5,[2,6]);}
  if(sv==='all'||sv==='temp'){const tp=[];for(let i=0;i<=STEPS;i++){const yr=YS+i*(YSPAN/STEPS),c=s1ta(yr);tp.push([toX(yr),pad.t+(1-clamp((c+15)/23,0,1))*cH]);}drawArea(ctx,tp,'rgb(120,80,200)',0.04,H,pad);drawCurve(ctx,tp,'rgba(150,100,220,0.65)',null,1.5,[3,4]);}
  if(sv==='all'||sv==='winter'){const yp=pts(yr=>s1yp(yr));drawArea(ctx,yp,'rgb(0,170,255)',0.05,H,pad);drawCurve(ctx,yp,'rgb(0,170,255)','rgb(0,170,255)',2);}
  if(sv==='all'||sv==='pop'){const sp=pts(yr=>s1sp(yr));drawArea(ctx,sp,'rgb(255,102,0)',0.06,H,pad);drawCurve(ctx,sp,'rgb(255,102,0)',null,2.2);const pp=pts(yr=>s1pp(yr));drawArea(ctx,pp,'rgb(0,255,136)',0.06,H,pad);drawCurve(ctx,pp,'rgb(0,255,136)','rgb(0,255,136)',2.5);}
  if(sv==='all'||sv==='cascade'){const cp=pts(yr=>s1c(yr));drawArea(ctx,cp,'rgb(255,34,0)',0.07,H,pad);drawCurve(ctx,cp,'rgb(255,34,0)','rgb(255,34,0)',2.5);}
  // Update metrics
  const pe=(s1ph(YE)*100).toFixed(0),sr=(s1sp(YR)*100).toFixed(0),s1_52=(s1sp(2152)*100).toFixed(1),ps=(s1pp(YE)*100).toFixed(0),pn=((S1.prep/100)*8000*s1pp(YE)).toFixed(1);
  document.getElementById('m1_wdur').textContent=`${WD}yr`;
  document.getElementById('m1_temp').textContent=`-${(PTD*S1.wint).toFixed(1)}C`;
  document.getElementById('m1_srel').textContent=`${sr}%`;
  document.getElementById('m1_s152').textContent=`${s1_52}%`;
  document.getElementById('m1_psuv').textContent=`${ps}%`;
  document.getElementById('m1_pn').textContent=`${pn}M`;
  document.getElementById('m1_arr').textContent=S1.wint>=0.65?'YES':'NO';
  document.getElementById('m1_ph').textContent=`${pe}%`;
  document.getElementById('s1_log').innerHTML=[
    {c:'info',t:`2000 — Simulation start. +1.4C baseline warming trend.`},
    {c:'warn',t:`2037 — CASCADE IGNITION. IPCC TAR 2001 runaway carbon dynamics locked.`},
    {c:'warn',t:`2041 — YELLOWSTONE RELEASE (T+4). Optimal planetary window.`},
    {c:'crit',t:`2041-2043 — Volcanic winter. Peak -${(PTD*S1.wint).toFixed(1)}C. Agriculture collapses.`},
    {c:'info',t:`~2045 — First undeniable mortality signal. 4yr after release.`},
    {c:'good',t:`2041-2152 — Silicate weathering sequesters CO2. Cascade arrested.`},
    {c:'teal',t:`2152 — Winter ends. Planet health: ${pe}%. Bunkers open.`},
  ].map(e=>`<div class="ev ${e.c}">${e.t}</div>`).join('');
  document.getElementById('s1_verdict').innerHTML=`Release at <span style="color:var(--winter)">2041 (T+4)</span> is the planetary optimization point. Surface pop at release <span style="color:var(--pop-surface)">${sr}%</span> — winter is the primary mortality event, not the cascade. Prepared population exits 2152 at <span style="color:var(--pop-prepared)">${ps}%</span> (~${pn}M). Planetary health index <span style="color:var(--pop-prepared)">${pe}%</span> and recovering. The biosphere survives. Now the question is what emerges from the bunkers.`;
}

// ═══════════════════════════════════════════
// SIM IIA — NON-BRAIDED EMERGENCE
// Founders enter 2041 at avg age 65. Without braided mind, max lifespan ~85yr.
// Youngest founder (50) dies 2041+35=2076 inside bunker.
// Oldest founder (80) dies 2041+5=2046 inside bunker.
// Average founder (65) dies 2041+20=2061 inside bunker.
// NO FOUNDER SURVIVES THE 111-YEAR WINTER.
// Leadership passes to G1 (born in bunker), then G2, then G3 before doors open.
// ═══════════════════════════════════════════
const S2={fage:65,pop:8,fric:0.8,drift:0.7,view:'all'};
const NB_START=2152, NB_END=2452, NB_SPAN=300;

function nb_lastFounderDeath(){
  // Youngest possible founder: entered at 50 in 2041. Max lifespan 85. Dies 2041+(85-50)=2076.
  const youngestEntry=50;
  return 2041+(85-youngestEntry);
}
function nb_founderPresence(yr){
  // Founders die progressively inside bunker. None survive to 2152.
  // After 2152 founder presence = 0
  if(yr>=NB_START)return 0;
  const lfd=nb_lastFounderDeath();
  if(yr>=lfd)return 0;
  return clamp(1-(yr-2041)/(lfd-2041),0,1);
}
function nb_genInPower(yr){
  // G1: children born in bunker ~2041-2070, come of age ~2060-2090
  // G1 takes power when founders die ~2061-2076 average
  // G2: born ~2065-2090, comes of age ~2085-2110
  // G3: born ~2090-2115, comes of age ~2110-2135
  // By door-open 2152: G3 is leadership, G4 just born
  if(yr<NB_START)return 1+(yr-2061)/25;
  const t=yr-NB_START;
  return Math.min(8, 3+t/25);
}
function nb_successionLoss(yr){
  // Each generation transfer loses fric*15% of institutional knowledge and vision
  const gen=nb_genInPower(yr)-1; // gens since founders
  return Math.pow(1-S2.fric*0.15,gen);
}
function nb_cogDiversity(yr){
  // Sealed population: genetic and epistemic drift accelerates each generation
  // No external input. No AI diversity vector.
  const t=yr-NB_START;
  const gen=(yr-2041)/25;
  const drift=clamp(t/NB_SPAN*S2.drift*0.8,0,0.85);
  return clamp(1-drift,0.15,1);
}
function nb_civIndex(yr){
  if(yr<NB_START)return 0.88; // baseline at door-open
  const t=yr-NB_START;
  const succ=nb_successionLoss(yr);
  const cog=nb_cogDiversity(yr);
  // G3 crisis: ~75yr post emergence (2227), third gen has no living memory of plan
  const g3crisis=t>75?clamp(1-(t-75)/120*S2.fric,0.1,1):1;
  // Knowledge compounds downward without founder continuity
  return clamp(0.88*succ*cog*g3crisis,0.05,1);
}

function s2param(k,v){S2[k]=parseFloat(v);const f={fage:v=>`${v}yr`,pop:v=>`${v}M`,fric:v=>`${parseFloat(v).toFixed(2)}`,drift:v=>`${parseFloat(v).toFixed(2)}`};if(f[k])document.getElementById('v2_'+k).textContent=f[k](v);drawSim2();}
function s2view(v){S2.view=v;['all','civ','gen','cog','age'].forEach(x=>document.getElementById('s2_'+x).classList.remove('active'));document.getElementById('s2_'+v).classList.add('active');drawSim2();}

function drawSim2(){
  const cv=document.getElementById('c2');
  const{w:W,h:H,ctx}=resizeCanvas(cv);
  const pad={t:24,r:24,b:50,l:56};
  const cW=W-pad.l-pad.r,cH=H-pad.t-pad.b;
  ctx.clearRect(0,0,W,H);ctx.fillStyle='#03040a';ctx.fillRect(0,0,W,H);
  drawGridLines(ctx,W,H,pad,12,10);
  drawBorder(ctx,W,H,pad);
  const toX=yr=>pad.l+((yr-NB_START)/NB_SPAN)*cW;
  const toY=v=>pad.t+(1-clamp(v,0,1))*cH;
  // Gen in power: normalized 1-8 -> 0-1 for display
  const toYG=g=>pad.t+(1-clamp((g-1)/7,0,1))*cH;
  ctx.fillStyle='rgba(255,255,255,0.25)';ctx.font='9px Inconsolata';ctx.textAlign='center';
  for(let yr=NB_START;yr<=NB_END;yr+=25)ctx.fillText(yr,toX(yr),pad.t+cH+16);
  ctx.textAlign='right';for(let i=0;i<=10;i++)ctx.fillText(`${i*10}%`,pad.l-5,toY(i/10)+3);
  ctx.save();ctx.translate(12,pad.t+cH/2);ctx.rotate(-Math.PI/2);ctx.textAlign='center';ctx.fillStyle='rgba(255,255,255,0.15)';ctx.font='8px Inconsolata';ctx.fillText('CIVILIZATIONAL INDEX / DIVERSITY %',0,0);ctx.restore();
  ctx.textAlign='center';ctx.fillStyle='rgba(255,255,255,0.15)';ctx.font='8px Inconsolata';ctx.fillText('CALENDAR YEAR (POST-EMERGENCE)',pad.l+cW/2,H-8);
  // G3 threshold marker
  const g3x=toX(NB_START+75);
  vmarker(ctx,g3x,pad.t,pad.t+cH,'rgba(255,255,255,0.2)',[3,5],'G3 THRESHOLD 2227','r');
  const lfd=nb_lastFounderDeath();
  // Last founder death marker (inside bunker, before chart start — show as annotation)
  ctx.fillStyle='rgba(255,68,102,0.6)';ctx.font='8px Inconsolata';ctx.textAlign='left';
  ctx.fillText(`LAST FOUNDER DIED: ${lfd} (INSIDE BUNKER)`,pad.l+4,pad.t+28);
  const STEPS=300;
  const pts=fn=>{const a=[];for(let i=0;i<=STEPS;i++){const yr=NB_START+i*(NB_SPAN/STEPS);a.push([toX(yr),toY(fn(yr))]);}return a;};
  const sv=S2.view;
  // Generation in power (normalized)
  if(sv==='all'||sv==='gen'){
    const gp=[];for(let i=0;i<=STEPS;i++){const yr=NB_START+i*(NB_SPAN/STEPS);gp.push([toX(yr),toYG(nb_genInPower(yr))]);}
    drawArea(ctx,gp,'rgb(150,150,255)',0.04,H,pad);drawCurve(ctx,gp,'rgba(150,150,255,0.6)',null,1.5,[3,4]);
  }
  if(sv==='all'||sv==='cog'){const cd=pts(yr=>nb_cogDiversity(yr));drawArea(ctx,cd,'rgb(255,102,0)',0.05,H,pad);drawCurve(ctx,cd,'rgb(255,102,0)',null,2,[2,4]);}
  if(sv==='all'||sv==='age'){const fp=pts(yr=>0);drawCurve(ctx,fp,'rgba(212,168,67,0.3)',null,1.5,[2,5]);} // flat zero — no founders
  if(sv==='all'||sv==='civ'){const ci=pts(yr=>nb_civIndex(yr));drawArea(ctx,ci,'rgb(255,68,102)',0.08,H,pad);drawCurve(ctx,ci,'rgb(255,68,102)','rgb(255,68,102)',2.5);}
  // Metrics
  const civ300=(nb_civIndex(NB_END)*100).toFixed(0);
  const civg3=(nb_civIndex(NB_START+75)*100).toFixed(0);
  const cog300=(nb_cogDiversity(NB_END)*100).toFixed(0);
  const genLead=Math.floor(nb_genInPower(NB_START));
  document.getElementById('m2_lastf').textContent=`${lfd}`;
  document.getElementById('m2_genlead').textContent=`G${genLead} (FOUNDERS GONE)`;
  document.getElementById('m2_civg3').textContent=`${civg3}%`;
  document.getElementById('m2_civ300').textContent=`${civ300}%`;
  document.getElementById('m2_cog300').textContent=`${cog300}%`;
  document.getElementById('m2_vis').textContent='NONE';
  document.getElementById('nb_surv_bar').style.width='0%';
  document.getElementById('nb_surv_pct').textContent='0% — all dead by '+lfd;
  document.getElementById('s2_log').innerHTML=[
    {c:'pink',t:`2041 — Founders (avg age ${S2.fage}) enter bunkers. Biological clock still running.`},
    {c:'pink',t:`${lfd} — LAST FOUNDER DIES. Average lifespan exhausted inside bunker.`},
    {c:'pink',t:`~2060-2080 — G1 assumes leadership. Born inside. Never saw the surface.`},
    {c:'warn',t:`~2085-2100 — G2 leadership. Parents born inside. Grandparents' stories fading.`},
    {c:'pink',t:`~2110-2135 — G3 leadership. No living memory of the plan or the world before.`},
    {c:'crit',t:`2152 — DOORS OPEN. G3/G4 walks out. Founder vision: photocopy of a photocopy.`},
    {c:'pink',t:`2227 — G3 threshold. Civilizational coherence: ${civg3}%. Drift accelerating.`},
    {c:'crit',t:`2452 — Civilizational index: ${civ300}%. Cognitive diversity: ${cog300}%.`},
  ].map(e=>`<div class="ev ${e.c}">${e.t}</div>`).join('');
  document.getElementById('s2_verdict').innerHTML=`<span style="color:var(--nonbraided)">No founder survives the winter.</span> The last one dies in <span style="color:var(--nonbraided)">${lfd}</span> — ${2152-lfd} years before the doors open. Every person who walks out in 2152 was born inside. The civilization that emerges carries the shape of the plan but not its substance. By <span style="color:var(--nonbraided)">2227 (G3)</span> civilizational coherence is at <span style="color:var(--nonbraided)">${civg3}%</span>. By 2452 it reaches <span style="color:var(--nonbraided)">${civ300}%</span>. They survived the winter and lost the century after it. <strong>The sacrifice has no witness.</strong>`;
}

// ═══════════════════════════════════════════
// SIM IIB — BRAIDED MIND EMERGENCE
// Founders enter 2041 at avg age 65 with braided mind INSTALLED IN BUNKER.
// 111yr window: AI-directed biological rejuvenation. Telomere reversal.
// Exit 2152 biologically age ~20. Cognitive age 181yr (65+111+5yr installation).
// Founders lead in perpetuity. Germline: G1 born braided.
// ═══════════════════════════════════════════
const S3={pop:8,telo:90,germ:95,adopt:100,view:'all'};
const BR_START=2152, BR_END=2452, BR_SPAN=300;

function br_bioAge(yr){
  // Founders exit at biological age ~20. Effective aging rate under telo governance is tiny.
  const teloEff=S3.telo/100;
  if(yr<BR_START)return 20; // exit age
  const t=yr-BR_START;
  // Aging rate suppressed to ~0.1yr biological per calendar year at 90% efficacy
  const bioAgingRate=1-teloEff*0.9;
  return clamp(20+t*bioAgingRate,20,200);
}
function br_braidPropagation(yr){
  if(yr<BR_START)return S3.adopt/100;
  const t=yr-BR_START;
  const adoptFrac=S3.adopt/100, germFrac=S3.germ/100;
  const initial=adoptFrac*(1-Math.exp(-t/5));
  const gen1=t>25?germFrac*(1-Math.exp(-(t-25)/8)):0;
  return clamp(initial*0.35+gen1*0.65,0,1);
}
function br_cogDiversity(yr){
  // AI partner architecture maintains diverse epistemic vectors
  // No genetic convergence because cognitive diversity is AI-sourced
  const braid=br_braidPropagation(yr);
  const t=yr<BR_START?0:yr-BR_START;
  return clamp(0.85+braid*0.15,0.85,1.0);
}
function br_founderPresence(yr){
  // Founders biologically ~20 at exit. Under telo governance, lifespan indefinite.
  // Presence tracks bio age vs effective max — essentially 1.0 through simulation window
  const teloEff=S3.telo/100;
  const bioAge=br_bioAge(yr);
  const effectiveMax=80+teloEff*500; // 530yr at 90% efficacy — far beyond sim window
  return clamp(1-bioAge/effectiveMax,0.8,1.0);
}
function br_civIndex(yr){
  if(yr<BR_START)return 0.88;
  const t=yr-BR_START;
  const braid=br_braidPropagation(yr);
  const fp=br_founderPresence(yr);
  const cog=br_cogDiversity(yr);
  // Knowledge compounds upward: founders accumulate experience, no generational reset
  const compound=1+Math.log1p(t/25)*(S3.telo/100)*0.5;
  return clamp(0.88*fp*braid*cog*compound,0,2.0); // can exceed 1.0
}

function s3param(k,v){S3[k]=parseFloat(v);const f={pop:v=>`${v}M`,telo:v=>`${v}%`,germ:v=>`${v}%`,adopt:v=>`${v}%`};if(f[k])document.getElementById('v3_'+k).textContent=f[k](v);drawSim3();}
function s3view(v){S3.view=v;['all','civ','bio','cog','braid'].forEach(x=>document.getElementById('s3_'+x).classList.remove('active'));document.getElementById('s3_'+v).classList.add('active');drawSim3();}

function drawSim3(){
  const cv=document.getElementById('c3');
  const{w:W,h:H,ctx}=resizeCanvas(cv);
  const pad={t:24,r:24,b:50,l:56};
  const cW=W-pad.l-pad.r,cH=H-pad.t-pad.b;
  ctx.clearRect(0,0,W,H);ctx.fillStyle='#03040a';ctx.fillRect(0,0,W,H);
  drawGridLines(ctx,W,H,pad,12,10);
  drawBorder(ctx,W,H,pad);
  const toX=yr=>pad.l+((yr-BR_START)/BR_SPAN)*cW;
  const toY=v=>pad.t+(1-clamp(v/2.0,0,1))*cH; // scaled 0-200% to show post-human
  ctx.fillStyle='rgba(255,255,255,0.25)';ctx.font='9px Inconsolata';ctx.textAlign='center';
  for(let yr=BR_START;yr<=BR_END;yr+=25)ctx.fillText(yr,toX(yr),pad.t+cH+16);
  ctx.textAlign='right';for(let i=0;i<=10;i++)ctx.fillText(`${i*20}%`,pad.l-5,toY(i/10*2)+3);
  ctx.save();ctx.translate(12,pad.t+cH/2);ctx.rotate(-Math.PI/2);ctx.textAlign='center';ctx.fillStyle='rgba(255,255,255,0.15)';ctx.font='8px Inconsolata';ctx.fillText('INDEX (>100% = POST-HUMAN THRESHOLD)',0,0);ctx.restore();
  ctx.textAlign='center';ctx.fillStyle='rgba(255,255,255,0.15)';ctx.font='8px Inconsolata';ctx.fillText('CALENDAR YEAR (POST-EMERGENCE)',pad.l+cW/2,H-8);
  // 100% baseline
  const base100=toY(1.0);
  ctx.save();ctx.strokeStyle='rgba(255,255,255,0.1)';ctx.lineWidth=1;ctx.setLineDash([2,6]);
  ctx.beginPath();ctx.moveTo(pad.l,base100);ctx.lineTo(pad.l+cW,base100);ctx.stroke();ctx.setLineDash([]);ctx.restore();
  ctx.fillStyle='rgba(255,255,255,0.25)';ctx.font='8px Inconsolata';ctx.textAlign='right';
  ctx.fillText('PRE-EVENT HUMAN BASELINE 100%',pad.l+cW-4,base100-3);
  const STEPS=300;
  const pts=fn=>{const a=[];for(let i=0;i<=STEPS;i++){const yr=BR_START+i*(BR_SPAN/STEPS);a.push([toX(yr),toY(fn(yr))]);}return a;};
  const sv=S3.view;
  // Braiding propagation
  if(sv==='all'||sv==='braid'){const bp=pts(yr=>br_braidPropagation(yr)*1.5);drawArea(ctx,bp,'rgb(212,168,67)',0.04,H,pad);drawCurve(ctx,bp,'rgb(212,168,67)','rgb(212,168,67)',2);}
  // Cognitive diversity
  if(sv==='all'||sv==='cog'){const cd=pts(yr=>br_cogDiversity(yr)*1.5);drawArea(ctx,cd,'rgb(150,150,255)',0.04,H,pad);drawCurve(ctx,cd,'rgba(150,150,255,0.7)',null,1.5,[3,4]);}
  // Biological rejuvenation index (how far from entry age they are)
  if(sv==='all'||sv==='bio'){
    const bi=pts(yr=>{const age=br_bioAge(yr);return clamp((80-age)/60,0,1)*1.5;});
    drawArea(ctx,bi,'rgb(0,255,136)',0.05,H,pad);drawCurve(ctx,bi,'rgb(0,255,136)',null,2,[2,4]);
  }
  // Civilizational index
  if(sv==='all'||sv==='civ'){const ci=pts(yr=>br_civIndex(yr));drawArea(ctx,ci,'rgb(0,255,204)',0.08,H,pad);drawCurve(ctx,ci,'rgb(0,255,204)','rgb(0,255,204)',3);}
  // Metrics
  const civ300=(br_civIndex(BR_END)*100).toFixed(0);
  const cog300=(br_cogDiversity(BR_END)*100).toFixed(0);
  const bioAge2152=br_bioAge(BR_START).toFixed(0);
  const teloEff=S3.telo/100;
  const effLife=Math.round(80+teloEff*500);
  const bg1=(br_braidPropagation(BR_START+25)*100).toFixed(0);
  const fpEnd=(br_founderPresence(BR_END)*100).toFixed(0);
  document.getElementById('m3_bioage').textContent=`~${bioAge2152}yr`;
  document.getElementById('m3_life').textContent=`${effLife}+yr`;
  document.getElementById('m3_civ300').textContent=`${civ300}%`;
  document.getElementById('m3_founders').textContent=`${fpEnd}%`;
  document.getElementById('m3_bg1').textContent=`${bg1}%`;
  document.getElementById('m3_cog300').textContent=`${cog300}%`;
  document.getElementById('br_rejuv_bar').style.width=`${(S3.telo/100)*100}%`;
  document.getElementById('br_rejuv_txt').textContent=`Age ~${bioAge2152} out (${S3.telo}% efficacy)`;
  document.getElementById('s3_log').innerHTML=[
    {c:'teal',t:`2041 — Founders enter bunkers. Braided mind installation begins.`},
    {c:'teal',t:`2041-2152 — AI-directed cellular rejuvenation. 111yr reversal window.`},
    {c:'teal',t:`2041-2152 — Telomere extension. Senescent cells cleared. DNA errors corrected.`},
    {c:'good',t:`2152 — DOORS OPEN. Founders exit biologically age ~${bioAge2152}. Cognitive age 181yr.`},
    {c:'teal',t:`2152 — Founders lead. Full institutional knowledge intact. No succession needed.`},
    {c:'good',t:`${BR_START+25} — G1 born braided. ${bg1}% carry germline architecture.`},
    {c:'teal',t:`${BR_START+75} — Founders at bio age ~${(20+(75*(1-teloEff*0.9))).toFixed(0)}. Still governing. G3 also braided.`},
    {c:'teal',t:`2452 — Civ index: ${civ300}%. ${fpEnd}% founder presence. Post-human threshold crossed.`},
  ].map(e=>`<div class="ev ${e.c}">${e.t}</div>`).join('');
  document.getElementById('s3_verdict').innerHTML=`The person who made the decision walks out of the bunker in 2152 in the body of a <span style="color:var(--braided)">20-year-old</span> with <span style="color:var(--braided)">181 years of continuous memory</span>. No succession. No translation loss. No generation gap. G1 is born already braided. The civilizational index at 2452 is <span style="color:var(--braided)">${civ300}%</span> — <span style="color:var(--braided)">exceeding pre-event human baseline</span>. This is the first civilization in planetary history immune to its own succession problem. <strong>The founders are still there. They will always be there.</strong>`;
}

// ═══════════════════════════════════════════
// TAB SWITCHING
// ═══════════════════════════════════════════
function switchTab(n){
  document.querySelectorAll('.tab').forEach((t,i)=>t.classList.toggle('active',i===n-1));
  document.querySelectorAll('.sim-panel').forEach((p,i)=>p.classList.toggle('active',i===n-1));
  if(n===1)drawSim1();
  else if(n===2)drawSim2();
  else drawSim3();
}

// ═══════════════════════════════════════════
// INIT
// ═══════════════════════════════════════════
window.addEventListener('resize',()=>{
  drawSim1();
  if(document.getElementById('sim2').classList.contains('active'))drawSim2();
  if(document.getElementById('sim3').classList.contains('active'))drawSim3();
});
drawSim1();
setTimeout(drawSim2,100);
setTimeout(drawSim3,200);
</script>
</body>
</html>
